#!@PYTHON3@
# SPDX-FileCopyrightText: Copyright (c) 2025-2026 NVIDIA CORPORATION & AFFILIATES. All rights reserved.
# SPDX-License-Identifier: BSD-3-Clause
# This module provide some functions GDB script can use to interact with an
# OpenOCD gdbserver instance.

import gdb
import re

open_ocd_conn = None
targets = []
active_target = None
daps = []
batch = None
batch_current_target = None

def check_attached():
    """ This function checks if we are attached to a target. If it fails it
    raises an error, otherwise returns nothing. It should be called once
    before using the other APIs or if the target may have disconnected."""
    global open_ocd_conn
    global targets
    conn = gdb.selected_inferior().connection
    if conn == None:
        raise gdb.GdbError("GDB is not attached to an OpenOCD instance, run target attach <ocdip>:<port> first.")
    elif not conn.is_valid():
        raise gdb.GdbError("The target connection is not valid (target lost or invalid).")
    elif type(conn) is not gdb.RemoteTargetConnection:
        raise gdb.GdbError("GDB is not attached to a valid remote target.")
    resp = gdb.execute("monitor version", False, True)
    if re.search("On-Chip Debugger", resp) == None:
        raise gdb.GdbError("The target we are attached to does not appear to be OpenOCD: %s." % resp)
    open_ocd_conn = conn
    daps = []
    targets = []

def quick_check_attached():
    """This function does an OPenOCD check but if it was done before only do
    a quick basic check. Raise an exception if we are not attached to OpenOCD."""
    global open_ocd_conn
    if open_ocd_conn != gdb.selected_inferior().connection:
        check_attached()
    elif not open_ocd_conn.is_valid():
        raise gdb.GdbError("The target disconnected since last check, not connected to OpenOCD.")

def select_target(target_name: str) -> str:
    """Tell Open OCD to switch the active target to <target>."""
    global active_target
    global targets
    global batch
    global batch_current_target
    quick_check_attached()
    get_targets()
    target = None
    for t in targets:
        if t['name'] == target_name:
            target = t
            break
    if target == None:
        gdb.GdbError("Target %s not found on the OpenOCD instance attached." % target_name)
    if batch != None:
        old_target_name = batch_current_target['name']
        if target != batch_current_target:
            # Eliminate the last target command if they are back to back
            if (len(batch) > 0) and batch[-1].startswith("targets "):
                del batch[-1]
            batch.append("targets %s" % target['name'])
            batch_current_target = target
    elif target != active_target:
        quick_check_attached()
        resp = gdb.execute("monitor targets %s" % target['name'], False, True)
        if resp != '':
            gdb.GdbError("Unexpected response when switching OpenOCD to target %s: %s." % (target['name'], resp))
        old_target_name = active_target['name']
        active_target = target
    else:
        old_target_name = active_target['name']
    return old_target_name

def read_memory(addr: int, width: int) -> int:
    """Do a read at address <addr> of size <width> bits using the active target. If
    batch mode is active this API will not return a value (value will be returned by
    execute_cmd_batch() and must be converted to int by caller)"""
    global batch
    if batch != None:
        batch.append("echo [read_memory 0x%x %d 1 phys]" % (addr, width))
        return None
    quick_check_attached()
    try:
        resp = gdb.execute("monitor read_memory 0x%x %d 1 phys" % (addr, width), False, True)
    except:
        raise gdb.GdbError("Read access at 0x%08x (%dbits) on target %s failed." % (addr, width, active_target['name']))
    try:
        # OpenOCD should return a 0x prefixed hex number
        return int(resp, 0)
    except:
        raise gdb.GdbError("Unexpected response when doing a read access at 0x%08x (%dbits): %s." % (addr, width, resp))

def write_memory(addr: int, width: int, value: int):
    """Do a write at address <addr> of <width> bits using the active target."""
    global batch
    if batch != None:
        batch.append("write_memory 0x%x %d {0x%x} phys" % (addr, width, value))
        return None
    quick_check_attached()
    try:
        resp = gdb.execute("monitor write_memory 0x%x %d {0x%x} phys" % (addr, width, value), False, True)
    except:
        raise gdb.GdbError("Write access at 0x%08x (%dbits) to target %s failed." % (addr, width, active_target['name']))
    if resp != '':
        raise gdb.GdbError("Unexpected response when doing a write access at 0x%08x (%dbits): %s." % (addr, width, resp))

def get_targets(detailed: bool = False) -> list:
    """List the targets supported by the OpenOCD instance GDB is attached to.
    The first entry is always the active target, the rest are ordered as
    provided by OpenOCD. If <detailed> is False then a simple list of names
    is returned, if <detailed> is True then a list of dictionaries is returned.
    """
    global active_target
    global targets
    quick_check_attached()
    # The targets list does not change at runtime so no need to refresh for
    # the basic list, but the target state does change thus update for detailed
    # queries.
    if (len(targets) == 0) or detailed:
        resp = gdb.execute("monitor targets", False, True)
        targets = []
        for line in resp.splitlines():
            elems = line.split(None)
            m = re.match(r'[0-9]+(\**)', elems[0])
            if m != None:
                entry = {'name': elems[1], 'type': elems[2], 'state': elems[5]}
                if m.group(1) == '*':
                    # The * was found indicating the active target
                    targets.insert(0, entry)
                else:
                    targets.append(entry)
        active_target = targets[0]
    if detailed:
        return targets
    else:
        return [t['name'] for t in targets]

def resume_target():
    """Resume the target."""
    global batch
    if batch != None:
        batch.append("resume")
        return
    quick_check_attached()
    gdb.execute("monitor resume")

def remotetimeout(timeout_ms: int = None):
    """Get or set OpenOCD's keep_alive timeout in milliseconds.
    If timeout_ms is provided, set the timeout; otherwise return the current
    value. Returns the configured timeout in milliseconds, or None when the
    attached OpenOCD does not support the remotetimeout command."""
    quick_check_attached()
    try:
        if timeout_ms is None:
            resp = gdb.execute("monitor remotetimeout", False, True)
        else:
            resp = gdb.execute("monitor remotetimeout %d" % timeout_ms, False, True)
    except gdb.error as e:
        raise gdb.GdbError("Failed to configure OpenOCD remotetimeout: %s" % e)
    m = re.search(r"remotetimeout:\s*(\d+)\s*ms", resp)
    if m is None:
        raise gdb.GdbError("Unexpected response when configuring OpenOCD remotetimeout: %s." % resp)
    return int(m.group(1))

def get_daps():
    global daps
    quick_check_attached()
    if len(daps) == 0:
        resp = gdb.execute("monitor dap names", False, True)
        for line in resp.splitlines():
            s = line.strip()
            if s and s.endswith(".dap"):
                daps.append(s)
    return daps

def execute(cmds):
    quick_check_attached()
    return_list = False
    if isinstance(cmds, str):
        cmd = cmds
    elif isinstance(cmds, list):
        return_list = True
        cmd = ';'.join(cmds)
    else:
        raise gdb.GdbError("OpenOCD execute() parameter must be a string or list.")
    try:
        result=gdb.execute("monitor %s" % cmd, False, True)
    except:
        raise gdb.GdbError("OpenOCD command '%s' failed to execute." % (cmd))
    if return_list:
        return [x for x in result.split('\n') if x]
    else:
        return result

# The 2 APIs below allow you to create a batch of OOCD commands that will be
# sent all at once to OpenOCD. Note that once you called start_cmd_batch all
# calls to OpenOCD  will be part of the batch until execute_cmd_batch is called
# thus make sure there is no interleaving happening.
def start_cmd_batch():
    global batch
    global batch_current_target
    batch = []
    batch_current_target = active_target

def execute_cmd_batch():
    global batch
    global batch_current_target
    if batch == None:
        raise gdb.GdbError("execute_cmd_batch() called without a prior call to start_cmd_batch().")
    try:
        result = execute(batch)
    except:
        # Make sure we cancel the batch
        abort_cmd_batch()
        raise
    active_target = batch_current_target
    batch = None
    return result

# Call this to cancel a batch when an exception occured
def abort_cmd_batch():
    global batch
    global batch_current_target
    active_target = batch_current_target
    batch = None

