"""
MMIO XML database loader for the axi command.

Parses OpenOCD/nvcpu-style mmio-xml files (as produced from JSON + address map)
and returns a structure compatible with gdbscripts/axi.py regspec:

  {
    "<component>": {
      "registers": {
        "<reg_name>": {
          "name", "title", "access", "width", "address", "fields": [...]
        }
      }
    }
  }

"""

from __future__ import annotations

import gzip
import os
import xml.etree.ElementTree as ET
from contextlib import nullcontext
from pathlib import Path
from typing import Any, Dict, List, Optional


def _local(tag: str) -> str:
    if tag.startswith("{"):
        return tag.split("}", 1)[1]
    return tag


def _parse_int(s: Optional[str], default: int = 0) -> int:
    if s is None or s == "":
        return default
    return int(s, 0)


def _field_from_elem(fel: ET.Element) -> Dict[str, Any]:
    hi = _parse_int(fel.get("high_bit"), 0)
    lo = _parse_int(fel.get("low_bit"), 0)
    reset = fel.get("hw_reset_value")
    try:
        reset_v = int(reset, 0) if reset is not None else 0
    except ValueError:
        reset_v = 0
    return {
        "name": fel.get("name") or "field",
        "bit_hi": hi,
        "bit_lo": lo,
        "bit_width": hi - lo + 1,
        "access": fel.get("sw") or "RW",
        "reset_value": reset_v,
    }


def _register_from_elem(rel: ET.Element) -> List[Dict[str, Any]]:
    name = rel.get("name")
    if not name:
        raise ValueError("register without name")
    offset = _parse_int(rel.get("offset"), 0)
    width = _parse_int(rel.get("size"), 32)
    doc_el = rel.find("doc")
    title = "".join(doc_el.itertext()).strip() if doc_el is not None else name
    fields: List[Dict[str, Any]] = []
    for child in rel:
        if _local(child.tag) != "field":
            continue
        fields.append(_field_from_elem(child))
    if not fields:
        fields.append(
            {
                "name": "value",
                "bit_hi": width - 1,
                "bit_lo": 0,
                "bit_width": width,
                "access": "RW",
                "reset_value": 0,
            }
        )
    access = fields[0]["access"] if len(fields) == 1 else "RW"

    def make_reg(reg_name: str, reg_offset: int) -> Dict[str, Any]:
        return {
            "name": reg_name,
            "title": title,
            "access": access,
            "width": width,
            "address": reg_offset,
            "fields": fields,
        }

    array_size_attr = rel.get("array_size")
    if array_size_attr is None:
        return [make_reg(name, offset)]

    size = _parse_int(array_size_attr, 1)
    stride = _parse_int(rel.get("array_stride"), (width + 7) // 8)
    regs = [make_reg(name, offset)]
    for idx in range(size):
        regs.append(make_reg(f"{name}_{idx}", offset + idx * stride))
    return regs


def _parse_mmio_xml_stream(path: str) -> Tuple[Dict[str, List[Dict[str, Any]]], List[Dict[str, Any]]]:
    """
    Single iterparse pass: reg_block_type templates and reg_block instances.

    Paths ending in ``.gz`` are read as gzip-compressed XML (matches
    ``gen-mmio-xml.py --gzip``).
    """
    types: Dict[str, List[Dict[str, Any]]] = {}
    blocks: List[Dict[str, Any]] = []
    type_stack: List[Optional[str]] = []

    src_ctx = gzip.open(path, "rb") if path.lower().endswith(".gz") else nullcontext(path)
    with src_ctx as source:
        for event, elem in ET.iterparse(source, events=("start", "end")):
            tag = _local(elem.tag)
            if event == "start":
                if tag == "reg_block_type":
                    tname = elem.get("name")
                    type_stack.append(tname)
                    if tname and tname not in types:
                        types[tname] = []
            else:
                if tag == "register":
                    if type_stack and type_stack[-1]:
                        types[type_stack[-1]].extend(_register_from_elem(elem))
                    elem.clear()
                elif tag == "reg_block_type":
                    type_stack.pop()
                    elem.clear()
                elif tag == "reg_block":
                    name = elem.get("name")
                    if name:
                        rb = elem.get("reg_block_type") or ""
                        blocks.append(
                            {
                                "name": name,
                                "base": _parse_int(elem.get("base"), 0),
                                "reg_block_type": [x.strip() for x in rb.split(",") if x.strip()],
                            }
                        )
                    elem.clear()
                # Do not clear on </field>: Element.clear() wipes attributes; parent
                # </register> has not run yet, so fields would lose name/high_bit/low_bit.
                elif tag in ("definitions", "define", "mmio-xml", "doc", "enum_entry"):
                    elem.clear()

    return types, blocks


def _die_tag_from_path(path: str) -> str:
    stem = Path(path).stem
    if "-" in stem:
        return stem.split("-", 1)[0]
    return stem


def _unique_reg_key(registers: Dict[str, Any], base_name: str) -> str:
    if base_name not in registers:
        return base_name
    n = 2
    while f"{base_name}__{n}" in registers:
        n += 1
    return f"{base_name}__{n}"


def parse_mmio_xml_file(path: str) -> Dict[str, Any]:
    """
    Parse a single mmio-xml file into axi regspec format.
    Component keys: <die_tag>_<reg_block.name> (e.g. vera_c_aon_car).
    """
    if not os.path.isfile(path):
        raise FileNotFoundError(f"MMIO XML not found: {path}")

    types, blocks = _parse_mmio_xml_stream(path)
    die = _die_tag_from_path(path).lower()
    out: Dict[str, Any] = {}

    for blk in blocks:
        type_names = blk["reg_block_type"]
        if not type_names:
            continue
        comp = f"{die}_{blk['name']}"
        base = blk["base"]
        registers: Dict[str, Any] = {}
        for tname in type_names:
            if tname not in types:
                continue
            for reg in types[tname]:
                r = dict(reg)
                r["address"] = base + int(reg["address"])
                key = _unique_reg_key(registers, reg["name"])
                registers[key] = r
        if registers:
            out[comp] = {"registers": registers}

    return out


def load_xml(paths: List[str]) -> Dict[str, Any]:
    """
    Load and merge MMIO XML files into one regspec dict.

    Args:
        paths: Non-empty list of XML filesystem paths. A path ending in
            ``.gz`` is read as gzip-compressed XML.

    Returns:
        Merged regspec for axi.Command.regspec.
    """
    if not paths:
        raise ValueError("load_xml requires at least one XML path")

    use = [os.path.expanduser(os.path.expandvars(p)) for p in paths]

    merged: Dict[str, Any] = {}
    for p in use:
        if not os.path.isfile(p):
            raise FileNotFoundError(f"MMIO XML not found: {p}")
        part = parse_mmio_xml_file(p)
        for comp, data in part.items():
            if comp in merged:
                # Same die+block from duplicate path: suffix
                n = 2
                alt = f"{comp}__{n}"
                while alt in merged:
                    n += 1
                    alt = f"{comp}__{n}"
                comp = alt
            merged[comp] = data
    return merged

#!@PYTHON3@
# SPDX-FileCopyrightText: Copyright (c) 2025-2026 NVIDIA CORPORATION & AFFILIATES. All rights reserved.
# SPDX-License-Identifier: BSD-3-Clause
# This file implement top level commands to support a Grace based
# system debug.

import apb
import axi
import openocd
import re
import gdb
import core

_GRACE_COMMAND_DOC_PUBLIC = """
    The grace command is used to attach to a Grace based target running OpenOCD.
    It supports the following subcommands:
    attach [ deadcores ] <host>[:<port>]
        Will attempt to connect to an instance of OpenOCD running on <host>
        using the parameters set in OpenOCD's standard grace.cfg configuration
        file.
        If deadcores is specified we will attach through the apb gdb port and
         present cores as if target was a perfect part. Controlling the cores
         and most data visualization features from GDB will be unavailable but
         this mode can be used to debug a core which does not respond.
    detach [ resume ]
        Detach from the OpenOCD target. If resume is specified the target will
        be resumed before detaching.
    """

class grace(gdb.Command):
    __doc__ = _GRACE_COMMAND_DOC_PUBLIC
    supported_commands = ['attach', 'detach']
    detach_options = ['resume']
    attach_options = ['deadcores', '<target_name_or_ip>']
    active_target = None

    def __init__(self):
        super(grace, self).__init__("grace", gdb.COMMAND_SUPPORT)

    def complete_helper_commands(self, textv, word, commands):
        """Helper function for code that would otherwise be duplicated"""
        if len(textv) == 0:
            return commands
        elif (len(textv) == 1) and (textv[0] == word):
                return [s for s in commands if s.startswith(word)]
        else:
            return None

    def complete(self, text, word):
        textv = gdb.string_to_argv(text)
        opts = self.complete_helper_commands(textv, word, self.supported_commands)
        if opts != None:
            return opts
        elif textv[0] == 'detach':
            # detach only support a subset of subcommands
            opts = self.complete_helper_commands(textv[1:], word, self.detach_options)
            if opts != None:
                return opts
        elif textv[0] == 'attach':
            if (word != None) and (word != ""):
                next_textv = [ textv[-1] ]
            else:
                next_textv = []
            opts = self.complete_helper_commands(next_textv, word, self.attach_options)
            if opts != None:
               return opts
        return gdb.COMPLETE_NONE

    def invoke(self, args, from_tty):
        argv = gdb.string_to_argv(args)
        if len(argv) == 0:
            raise gdb.GdbError("The grace command needs arguments, try 'help grace'.")
        elif argv[0] == "attach":
            self.dont_repeat()
            if not self.active_target is None:
                raise gdb.GdbError("Already attached to %s, run 'grace detach [resume]' first." % self.active_target)
            host = None
            self.deadcores_attach = False
            self.ccplex_attach = True
            for arg in argv[1:]:
                if arg == "deadcores":
                    self.deadcores_attach = True
                elif host == None:
                    host = arg
                else:
                    raise gdb.GdbError("Invalid syntax for grace attach command '%s', try 'help vera'." % args)
            hostv = host.split(':')
            if (len(hostv) < 1) or (len(hostv) > 2):
                raise gdb.GdbError("Invalid host name '%s' for grace attach command." % host)
            elif len(hostv) == 1:
                # Append default port
                if self.deadcores_attach:
                    hoststr = "%s:10002" % hostv[0]
                else:
                    hoststr = "%s:10000" % hostv[0]
            else:
                hoststr = "%s:%s" % (hostv[0], hostv[1])
            # One second with many cores is not enough
            gdb.execute("set remotetimeout 60000")
            # Attach to OpenOCD target
            print("Attaching to OpenOCD running at %s..." % hoststr)
            try:
                gdb.execute("target extended-remote %s" % hoststr)
            except:
                if self.deadcores_attach:
                    raise gdb.GdbError("Unable to reach out to %s. Check the"
                                        " address." % hoststr)
                else:
                    raise gdb.GdbError("Unable to reach out to %s. Check the"
                                        " address and if correct try "
                                        "'grace %s deadcores'" % (hoststr, args))
            self.active_target = hoststr
            # Tell openocd about the new gdb remotetimeout.
            try:
                openocd.remotetimeout(60000)
            except gdb.GdbError as e:
                # Don't stop attach if the command is not supported
                print("Warning: %s" % e)
            # Check if we are attached to Grace
            targets = openocd.get_targets(True)
            if (len(targets) == 0) or (not targets[0]['name'].startswith('grace')):
                raise gdb.GdbError("The target attached is not a Grace target.")
            # Configure the Core command
            # Figure out if we should attach to GDB threads or not based on
            # whether all cores are halted
            system_halted = False
            for tgt in targets:
                if tgt['state'] == 'halted':
                    if self.ccplex_attach and (tgt['name'].rfind('.core') != -1):
                        system_halted = True
            # Configure the Core command. Disable the attach feature is it would take too long.
            if self.deadcores_attach:
                core_attach = False
            elif system_halted:
                core_attach = True
            else:
                print("No core found halted, assuming we are in nonstop-attach mode.")
                core_attach = False
            core.core_control.configure({
                'platform_name': 'grace',
                'cores_per_chiplet': 84,
                'max_chiplets': 4,
                'apb_base': 0x10200000,
                'core_offset': 0x200000,
                'attach_mode': core_attach,
                'chiplet_offset': 0x100000000000,
                'dummy_cores_mode': self.deadcores_attach,
            })
            if self.ccplex_attach:
                # Load the APB database for Olympus
                apb_res_file = "%s/res/apbDB-demeter-core.yml" % nvgdb_dir
                if os.path.isfile(apb_res_file):
                    gdb.execute("apb load %s" % apb_res_file)
                else:
                    print("APB registers database for Demeter not loaded: %s not found." % apb_res_file)
                # Configure the SPR command to use OpenOCD MRS/MSR
                gdb.execute("spr set access openocd")
                # Load the SPR database
                spr_res_file = "%s/res/sprDB-demeter-core.yml.gz" % nvgdb_dir
                if os.path.isfile(spr_res_file):
                    gdb.execute("spr load %s" % spr_res_file)
                else:
                    print("SPR registers database for Demeter not loaded: %s not found." % spr_res_file)
            # Configure the MMIO interface
            axi_res_file = "%s/res/Grace-MMIO.xml.gz" % nvgdb_dir
            if os.path.isfile(axi_res_file):
                print("AXI registers database for Grace will be loaded when needed.")
                axi.axi_reg_access.set_db([axi_res_file])
            else:
                print("AXI registers database for Grace will not be loaded: %s not found." % axi_res_file)
            axi_openocd_target = None
            for t in openocd.get_targets():
                if re.search("^grace.[0-9]+.axi$", t) != None:
                    axi_openocd_target = "grace.<chiplet>.axi"
                    break
            if axi_openocd_target != None:
                gdb.execute("axi set access openocd %s" % axi_openocd_target)
            else:
                gdb.execute("axi set access openocd <core>")
            gdb.execute("axi set chiplet_offset 0x100000000000")
            # List valid cores
            print("Attached to OpenOCD running at %s:" % hoststr)
            gdb.execute("core list")
            # Pick the one currently active as the debug core
            print("Currently debugging core %s" % gdb.execute("core", False, True))
        elif argv[0] == "detach":
            self.dont_repeat()
            if self.active_target is None:
                raise gdb.GdbError("No active grace target to detach from.")
            elif gdb.selected_inferior().connection == None:
                print("Connection to OpenOCD running on %s has been lost already, clearing state." % self.active_target)
                self.active_target = None
            elif len(argv) == 1:
                try:
                    gdb.execute("detach")
                    print("Detached from OpenOCD running on %s." % self.active_target)
                except Exception as e:
                    print("An error occured while detaching: %s. Assume connection is lost." % e)
                self.active_target = None
            elif (len(argv) == 2) and (argv[1] == "resume"):
                if self.deadcores_attach:
                    raise gdb.GdbError("Unable to resume target in deadcores mode, try without resume.")
                openocd.resume_target()
                try:
                    gdb.execute("detach")
                    print("Detached from OpenOCD running on %s and resumed target." % self.active_target)
                except Exception as e:
