class brbe(gdb.Command):
    """This command accesses the BRBE records for the current PE. It supports
    the following subcommands:
    read [Record number]
        Read and display all of the valid branch records for the current PE, or a 
         specific record if a record number is specified.
    config <parameter> [ <args> ]
        enable [el0|el1|el2]: Enable BRB recording for specified EL level.
            If no EL is specified, enables all EL levels (EL0, EL1, and EL2).
        disable [el0|el1|el2]: Disable BRB recording for specified EL level.
            If no EL is specified, disables all EL levels (EL0, EL1, and EL2).
        debug: on | off: enable or disable extra debug messages.
    """
    supported_commands = ['read', 'config']
    debug = False
    number_of_records = 64

    def __init__(self):
        super(brbe, self).__init__("brbe", gdb.COMMAND_DATA)

    def decode_cycle_count(self, cc_encoded):
        """Decode the cycle count from mantissa/exponent encoding.

        Encoding format (ARM BRBE specification):
        - If E == 0: value = M
        - If E != 0: value = UInt('1':M:Zeros(UInt(E)-1))
          This means: concatenate binary '1' + M (as binary) + (E-1) zeros
        - All ones in both M and E indicates overflow

        Bit positions:
        - M (mantissa): bits [7:0] (8 bits)
        - E (exponent): bits [13:8] (6 bits)

        Args:
            cc_encoded: The encoded cycle count value (14 bits from INF register bits [45:32])

        Returns:
            Decoded cycle count as integer, or "Overflow" if all ones, or None if invalid
        """
        # Extract E and M from the 14-bit encoded value
        # M (mantissa): bits [7:0] = 8 bits
        # E (exponent): bits [13:8] = 6 bits
        M = cc_encoded & 0xFF          # 8 bits for mantissa [7:0]
        E = (cc_encoded >> 8) & 0x3F  # 6 bits for exponent [13:8]

        # Check for overflow (all ones in both E and M)
        if E == 0x3F and M == 0xFF:
            return "Overflow"

        # Decode according to formula
        if E == 0:
            # If E is zero, value is just the mantissa
            return M
        else:
            result = (256 + M) << (E - 1)
            return result

    def addr_to_symbol(self, addr):
        """Convert an address to a symbol string using GDB's symbol lookup."""
        try:
            addr_int = int(addr)
            # Use info symbol command to get symbol name
            result = gdb.execute("info symbol 0x{:x}".format(addr_int), False, True).strip()

            # Parse the result - format can be:
            # "symbol_name in section"
            # "symbol_name + offset in section"
            # "No symbol matches 0x..."
            if result.startswith("No symbol matches"):
                return ""

            # Extract symbol name and optional offset
            if " in " in result:
                symbol_part = result.split(" in ")[0].strip()
                # Check if there's an offset (e.g., "function_name + 0x10")
                if " + " in symbol_part:
                    parts = symbol_part.split(" + ")
                    symbol_name = parts[0].strip()
                    offset = parts[1].strip()
                    return " <{}+{}>".format(symbol_name, offset)
                else:
                    return " <{}>".format(symbol_part)
            elif result:
                # Just the symbol name without section info
                return " <{}>".format(result)
        except Exception as e:
            if self.debug:
                print("Error looking up symbol for 0x{:x}: {}".format(addr, str(e)))
        return ""

    def complete_helper_commands(self, textv, word, commands):
        """Helper function for code that would otherwise be duplicated"""
        if len(textv) == 0:
            return commands
        elif (len(textv) == 1) and (textv[0] == word):
                return [s for s in commands if s.startswith(word)]
        else:
            return None

    def complete(self, text, word):
        textv = gdb.string_to_argv(text)
        # First we ignore all optional arguments
        for arg in list(textv):
            if arg.startswith('/'):
                textv.remove(arg)
        # If completion is on command type return the intersect of word
        # and the supported commands.
        opts = self.complete_helper_commands(textv, word, self.supported_commands)
        if opts != None:
            return opts
        elif textv[0] == 'read':
            # If there is an argument, it should be a number 
            if len(textv) <= 2:
