        else:
            raise gdb.GdbError("INTERNAL ERROR: unhandled command '%s'" % argv[0])

    def enable_brbe(self, el=None):
        """Enable BRBE recording by setting the appropriate control registers.

        Args:
            el: Optional EL level to enable ('el0', 'el1', 'el2', or None for all)
        """
        try:
            if not hasattr(spr_reg_access, 'regspec_loader') or spr_reg_access.regspec_loader is None:
                print("Warning: SPR database not loaded")
                return

            # Enable BRBE recording non-matches by setting BRBFCR_EL1.ENI = 1
            try:
                fcr_reg = spr_reg_access.lookup_reg_by_name('brbfcr_el1')
                if fcr_reg is None:
                    if self.debug:
                        print("BRBFCR_EL1 register not found in database")
                    return False

                # Read current FCR value
                fcr_value = spr_reg_access.read_spr(fcr_reg)

                # Set eni bit (bit 16)
                fcr_value = (1 << 16)

                # Write back the FCR register
                spr_reg_access.write_spr(fcr_reg, fcr_value)
                print("BRBE recording include non-matches (BRBFCR_EL1.ENI = 1)")
            except Exception as e:
                if self.debug:
                    print("Note: Could not enable BRBE via BRBFCR_EL1: {}".format(str(e)))

            el1_mask = 0x38 # cc | mpred | vts
            el2_mask = 0x18 # cc | mpred

            if el is None:
                # Enable all ELs
                el1_mask |= 0xC00003  # e0bre | e1bre | ertn | exception
                el2_mask |= 0xC00003  # e0hbre | e2bre | ertn | exception
                print("Enabling BRBE recording for all EL levels (EL0, EL1, EL2)")
            elif el == 'el0':
                # Enable only EL0
                el1_mask |= 0x1  # e0bre
                el2_mask |= 0x1  # e0hbre
                print("Enabling BRBE recording for EL0")
            elif el == 'el1':
                # Enable only EL1
                el1_mask |= 0xC00002  # e1bre | ertn | exception
                print("Enabling BRBE recording for EL1")
            elif el == 'el2':
                # Enable only EL2
                el2_mask |= 0xC00002  # e2bre | ertn | exception
                print("Enabling BRBE recording for EL2")

            # Write to BRBCR_EL1
            try:
                brbcr_reg = spr_reg_access.lookup_reg_by_name('brbcr_el1')
                if brbcr_reg is not None:
                    el1_value = spr_reg_access.read_spr(brbcr_reg)
                    el1_value |= el1_mask

                    spr_reg_access.write_spr(brbcr_reg, el1_value)
                else:
                    print("Warning: BRBCR_EL1 register not found in database")
            except Exception as e:
                print("Warning: Could not enable BRBE via BRBCR_EL1: {}".format(str(e)))

            # Write to BRBCR_EL2
            try:
                brbcr2_reg = spr_reg_access.lookup_reg_by_name('brbcr_el2')
                if brbcr2_reg is not None:
                    el2_value = spr_reg_access.read_spr(brbcr2_reg)
                    el2_value |= el2_mask

                    spr_reg_access.write_spr(brbcr2_reg, el2_value)
                else:
                    if self.debug:
                        print("Note: BRBCR_EL2 register not found in database")
            except Exception as e:
                if self.debug:
                    print("Note: Could not enable BRBE via BRBCR_EL2: {}".format(str(e)))

        except Exception as e:
            print("Error enabling BRBE: {}".format(str(e)))

    def disable_brbe(self, el=None):
        """Disable BRBE recording by clearing the appropriate control registers.

        Args:
            el: Optional EL level to disable ('el0', 'el1', 'el2', or None for all)
        """
        try:
            if not hasattr(spr_reg_access, 'regspec_loader') or spr_reg_access.regspec_loader is None:
                print("Warning: SPR database not loaded")
                return

            el1_mask = 0
            el2_mask = 0

            if el is None:
                # Disable all ELs
                el1_mask = 0xC00003  # e0bre | e1bre | ertn | exception
                el2_mask = 0xC00003  # e0hbre | e2bre | ertn | exception
                print("Disabling BRBE recording for all EL levels (EL0, EL1, EL2)")
            elif el == 'el0':
                # Disable only EL0
                el1_mask = 0x1  # e0bre
                el2_mask = 0x1  # e0hbre
                print("Disabling BRBE recording for EL0")
            elif el == 'el1':
                # Disable only EL1
                el1_mask = 0xC00002  # e1bre | ertn | exception
                print("Disabling BRBE recording for EL1")
            elif el == 'el2':
                # Disable only EL2
                el2_mask = 0xC00002  # e2bre | ertn | exception
                print("Disabling BRBE recording for EL2")

            # Write to BRBCR_EL1
            try:
                brbcr_reg = spr_reg_access.lookup_reg_by_name('brbcr_el1')
                if brbcr_reg is not None:
                    el1_value = spr_reg_access.read_spr(brbcr_reg)
                    el1_value &= ~el1_mask

                    spr_reg_access.write_spr(brbcr_reg, el1_value)
                else:
                    print("Warning: BRBCR_EL1 register not found in database")
            except Exception as e:
                print("Warning: Could not disable BRBE via BRBCR_EL1: {}".format(str(e)))

            # Write to BRBCR_EL2
            try:
                brbcr2_reg = spr_reg_access.lookup_reg_by_name('brbcr_el2')
                if brbcr2_reg is not None:
                    el2_value = spr_reg_access.read_spr(brbcr2_reg)
                    el2_value &= ~el2_mask

                    spr_reg_access.write_spr(brbcr2_reg, el2_value)
                else:
                    if self.debug:
                        print("Note: BRBCR_EL2 register not found in database")
            except Exception as e:
                if self.debug:
                    print("Note: Could not disable BRBE via BRBCR_EL2: {}".format(str(e)))

        except Exception as e:
            print("Error disabling BRBE: {}".format(str(e)))

    def pause_brbe(self, pause):
        """Pause or unpause BRBE recording by setting/clearing bit 7 in BRBFCR_EL1.

        Args:
            pause: True to pause BRBE recording, False to unpause
        """
        try:
            if not hasattr(spr_reg_access, 'regspec_loader') or spr_reg_access.regspec_loader is None:
                print("Warning: SPR database not loaded")
                return

            try:
                fcr_reg = spr_reg_access.lookup_reg_by_name('brbfcr_el1')
                if fcr_reg is None:
                    if self.debug:
                        print("BRBFCR_EL1 register not found in database")
                    return

                # Read current FCR value
                fcr_value = spr_reg_access.read_spr(fcr_reg)

                # Set or clear bit 7 based on pause parameter
                if pause:
                    fcr_value |= (1 << 7)  # Set bit 7 to pause
                else:
                    fcr_value &= ~(1 << 7)  # Clear bit 7 to unpause

                # Write back the FCR register
                spr_reg_access.write_spr(fcr_reg, fcr_value)

                if self.debug:
                    print("BRBE recording {} (BRBFCR_EL1.PAUSED = {})".format("paused" if pause else "unpaused", 1 if pause else 0))
            except Exception as e:
                if self.debug:
                    print("Note: Could not {} BRBE via BRBFCR_EL1: {}".format("pause" if pause else "unpause", str(e)))

        except Exception as e:
            if self.debug:
                print("Error {} BRBE: {}".format("pausing" if pause else "unpausing", str(e)))

    def read_number_of_records(self):
        """Read the number of records from the BRBIDR0_EL1 register."""
        try:
            if not hasattr(spr_reg_access, 'regspec_loader') or spr_reg_access.regspec_loader is None:
                print("Warning: SPR database not loaded")
                return

            # Read the number of records from the BRBE control registers
            brbidr0_reg = spr_reg_access.lookup_reg_by_name('brbidr0_el1')
            if brbidr0_reg is None:
                print("BRBIDR0_EL1 register not found in database")
                return 0

            # Read the number of records from the BRBIDR0_EL1 register
            brbidr0_value = spr_reg_access.read_spr(brbidr0_reg)
            return brbidr0_value & 0xFF
        except Exception as e:
            print("Error reading number of records: {}".format(str(e)))
            return 0

    def brbe_record_valid(self, record_number):
        # Set the bank to the correct bank for the record number
        try:
            if not hasattr(spr_reg_access, 'regspec_loader') or spr_reg_access.regspec_loader is None:
                print("Warning: SPR database not loaded")
                return

            # Get the FCR register and read current value
            fcr_reg = spr_reg_access.lookup_reg_by_name('brbfcr_el1')
            if fcr_reg is None:
                if self.debug:
                    print("BRBFCR_EL1 register not found in database")
                return False

            # Read current FCR value
            fcr_value = spr_reg_access.read_spr(fcr_reg)

            # Set bank bit (bit 28: 0=bank0, 1=bank1)
            bank_bit = 1 if record_number > 31 else 0
            fcr_value = (fcr_value & ~0x10000000) | (bank_bit << 28)

            # Write back the FCR register
            spr_reg_access.write_spr(fcr_reg, fcr_value)

            # Read the valid bit from the record
            inf_reg_name = 'brbinf%d_el1' % (record_number % 32)
            inf_reg = spr_reg_access.lookup_reg_by_name(inf_reg_name)
            if inf_reg is None:
                if self.debug:
                    print("Register {} not found in database".format(inf_reg_name))
                return False

            # Read the INF register value
            inf_value = spr_reg_access.read_spr(inf_reg)

            if self.debug:
                print("Record {}: INF register = 0x{:x}, valid = 0x{:x}".format(record_number, inf_value, (inf_value & 0x3)))

            # Extract valid field
            return (inf_value & 0x3) != 0

        except Exception as e:
            if self.debug:
                print("Error reading BRBE record validity: {}".format(str(e)))
            return False

    def read_brbe_record(self, record_number):
        # Set the bank to the correct bank for the record number
        try:
            if not hasattr(spr_reg_access, 'regspec_loader') or spr_reg_access.regspec_loader is None:
                print("Warning: SPR database not loaded")
                return

            # Get the FCR register and read current value
            fcr_reg = spr_reg_access.lookup_reg_by_name('brbfcr_el1')
            if fcr_reg is None:
                print("BRBFCR_EL1 register not found in database")
                return

            # Read current FCR value
            fcr_value = spr_reg_access.read_spr(fcr_reg)

            # Set bank bit (bit 28: 0=bank0, 1=bank1)
            bank_bit = 1 if record_number > 31 else 0
            fcr_value = (fcr_value & ~0x10000000) | (bank_bit << 28)

            # Write back the FCR register
            spr_reg_access.write_spr(fcr_reg, fcr_value)

            # Read the record registers
            inf_reg_name = 'brbinf%d_el1' % (record_number % 32)
            src_reg_name = 'brbsrc%d_el1' % (record_number % 32)
            tgt_reg_name = 'brbtgt%d_el1' % (record_number % 32)

            # Read INF register
            inf_reg = spr_reg_access.lookup_reg_by_name(inf_reg_name)
            if inf_reg is None:
                print("Register {} not found in database".format(inf_reg_name))
                return

            inf_value = spr_reg_access.read_spr(inf_reg)

            # Read SRC register
            src_reg = spr_reg_access.lookup_reg_by_name(src_reg_name)
            if src_reg is None:
                print("Register {} not found in database".format(src_reg_name))
                return

            src_value = spr_reg_access.read_spr(src_reg)

            # Read TGT register
            tgt_reg = spr_reg_access.lookup_reg_by_name(tgt_reg_name)
            if tgt_reg is None:
                print("Register {} not found in database".format(tgt_reg_name))
                return

            tgt_value = spr_reg_access.read_spr(tgt_reg)

            if self.debug:
                if self.debug:
                    print("Record {}: INF=0x{:x}, SRC=0x{:x}, TGT=0x{:x}".format(record_number, inf_value, src_value, tgt_value))

            # Extract fields from the register values
            # Note: These bit positions are assumptions - actual implementation
            # would need to be verified against the hardware specification
            valid = inf_value & 0x3
            record_type = (inf_value >> 8) & 0x3F
            mpred = (inf_value >> 5) & 0x1
            el = (inf_value >> 6) & 0x3
            cc_encoded = (inf_value >> 32) & 0x3FFF  # 14 bits for encoded cycle count
            ccu = (inf_value >> 46) & 0x1

            num_str = str(record_number).ljust(3)

            # Decode cycle count from mantissa/exponent encoding
            if ccu == 1:
                cc_str = "-"
            else:
                cc_decoded = self.decode_cycle_count(cc_encoded)
                if cc_decoded == "Overflow":
                    cc_str = "Overflow"
                else:
                    cc_str = str(cc_decoded)

            if valid == 2 or valid == 3:
                mpred_str = str(mpred)
                src_str = "0x{:016x}".format(src_value)
                src_sym = self.addr_to_symbol(src_value)
            else:
                mpred_str = "-"
                src_str = "-"
                src_sym = ""

            if valid == 1 or valid == 3:
                el_str = str(el)
                tgt_str = "0x{:016x}".format(tgt_value)
                tgt_sym = self.addr_to_symbol(tgt_value)
            else:
                el_str = "-"
                tgt_str = "-"
                tgt_sym = ""

            if valid != 0:
                print("%s | 0x%x   | 0x%02x | %s | %s | %s | %s%s | %s%s" %
                      (num_str, valid, record_type, mpred_str.ljust(5), el_str.ljust(6), cc_str.ljust(12),
                      src_str.ljust(18), src_sym, tgt_str.ljust(18), tgt_sym))
            else:
                if self.debug:
                    print("Record %d is not valid." % record_number)

        except Exception as e:
            print("Error reading BRBE record {}: {}".format(record_number, str(e)))

    def cmd_read(self, argv, from_tty):
        record_number = -1
        self.number_of_records = self.read_number_of_records()
        if len(argv) > 2:
            raise gdb.GdbError("Too many arguments to %s command. Try 'help brbe'." % ' '.join(argv[0:1]))
        elif len(argv) == 2:
            try:
                record_number = int(argv[1], 0)
                if record_number >= self.number_of_records:
                    raise gdb.GdbError("Record number %d is out of range. Try 'help brbe'." % record_number)
            except:
                raise gdb.GdbError("Number expected to %s command. Try 'help brbe'." % ' '.join(argv[0:1]))

        print("Num | Valid | Type | MPRED | TGT EL | Clock Cycles | SRC                | TGT")
        print("=" * 92)

        try:
            self.pause_brbe(True)

            valid_records = 0
            if record_number > -1:
                # Check specific record
                if self.brbe_record_valid(record_number):
                    self.read_brbe_record(record_number)
                    valid_records += 1
                else:
                    print("Record %d is not valid." % record_number)
            else:
                # Check all records
                for record_num in range(self.number_of_records):
                    if self.brbe_record_valid(record_num):
                        self.read_brbe_record(record_num)
                        valid_records += 1

            print("=" * 92)
            print("Found %d valid BRBE records out of %d total records." % (valid_records, self.number_of_records))
        finally:
            # Always unpause BRBE, even if user quits pager early
            self.pause_brbe(False)

        if valid_records == 0:
            print("No valid BRBE records found. This could mean:")
            print("  - BRBE is not enabled (try 'brbe config enable')")
            print("  - No branch instructions have been executed")
            print("  - BRBE records have been cleared")
            print("  - Debug mode: try 'brbe config debug on' for more information")

    def cmd_config(self, argv, from_tty):
        if len(argv) < 2:
            raise gdb.GdbError("Invalid syntax, %s command requires a parameter. Try 'help brbe'." % argv[0])
        if argv[1] == 'enable':
            # Parse optional EL argument
            el = None
            if len(argv) > 2:
                el = argv[2].lower()
                if el not in ['el0', 'el1', 'el2']:
                    raise gdb.GdbError("Invalid EL '%s'. Expected 'el0', 'el1', or 'el2'." % argv[2])
            self.enable_brbe(el)
        elif argv[1] == 'disable':
            # Parse optional EL argument
            el = None
            if len(argv) > 2:
                el = argv[2].lower()
                if el not in ['el0', 'el1', 'el2']:
                    raise gdb.GdbError("Invalid EL '%s'. Expected 'el0', 'el1', or 'el2'." % argv[2])
            self.disable_brbe(el)
        elif argv[1] == 'debug':
            if len(argv) == 2:
                print("BRBE debug mode is currently %s." % ('enabled' if self.debug else 'disabled'))
            elif len(argv) > 3:
                raise gdb.GdbError("Invalid argument '%s' to %s." % (' '.join(argv[2:]), ' '.join(argv[0:1])))
            elif argv[2] == 'on':
                self.debug = True
                print("BRBE debug mode is now enabled.")
            elif argv[2] == 'off':
                self.debug = False
                print("BRBE debug mode is now disabled.")
            else:
                raise gdb.GdbError("Invalid argument '%s' to %s." % (argv[2], ' '.join(argv[0:1])))
        else:
            raise gdb.GdbError("Unknown %s subcommand %s. Try 'help brbe'." % (argv[0], argv[1]))

# Instantiate the command
brbe()

