        return None

def _script_dir():
    try:
        return os.path.dirname(os.path.abspath(__file__))
    except NameError:
        return os.getcwd()

def _dedupe_paths(paths, keep=None):
    """Return absolute, de-duplicated paths, preserving order.

    If ``keep`` is given, only paths satisfying ``keep(path)`` are returned
    (and rejected paths do not consume their de-dup slot).
    """
    result = []
    seen = set()
    for path in paths:
        if not path:
            continue
        path = os.path.abspath(path)
        if path in seen:
            continue
        if keep is not None and not keep(path):
            continue
        seen.add(path)
        result.append(path)
    return result

def _normalize_command(command):
    return re.sub(r"\s+", " ", command.strip())

def _command_prefix_matches(command, prefixes):
    command = _normalize_command(command).lower()
    for prefix in prefixes:
        if command == prefix or command.startswith(prefix + " "):
            return True
    return False

def _command_contains_blocked_word(command):
    for token in re.split(r"[^a-zA-Z0-9_]+", _normalize_command(command).lower()):
        for word in BLOCKED_WORDS:
            if token == word or token.startswith(word + "_"):
                return True
    return False

def _is_discovered_info_command(command):
    argv = _normalize_command(command).lower().split(None, 2)
    if len(argv) < 2 or argv[1] != "info":
        return False
    info_commands = {
        item["command"].lower()
        for item in _discover_gdbscript_commands()
        if "info" in item.get("subcommands", [])
    }
    return argv[0] in info_commands

def _is_command_safe(command):
    command = _normalize_command(command)
    if not command:
        return False
    if "\n" in command or "\r" in command:
        return False
    if _command_prefix_matches(command, READ_ONLY_PREFIXES):
        return True
    if _is_discovered_info_command(command):
        return True
    if _command_prefix_matches(command, BLOCKED_PREFIXES):
        return False
    if _command_contains_blocked_word(command):
        return False
    return False

def _approved_by_user(command, reason):
    gdb.write("ai wants to run a command that may change state:\n")
    gdb.write("  %s\n" % command)
    if reason:
        gdb.write("Reason: %s\n" % reason)
    try:
        response = input("Run this command? [y/N] ")
    except EOFError:
        return False
    return response.strip().lower() in ("y", "yes")

def _candidate_skill_paths():
    skill_rel = (".agents", "skills", "gdbscripts", "SKILL.md")
    share_dir = _nvgdb_dir()
    script_dir = _script_dir()

    paths = [os.environ.get(SKILL_ENV_VAR)]
    if share_dir:
        paths.append(os.path.join(share_dir, *skill_rel))
    paths.append(os.path.join(script_dir, *skill_rel))
    return _dedupe_paths(paths)

def _load_skill_context():
    for path in _candidate_skill_paths():
        if not os.path.isfile(path):
            continue
        try:
            with open(path, "r", encoding="utf-8") as f:
                return path, f.read()
        except OSError:
            continue
    return None, ""

def _python_dirs():
    share_dir = _nvgdb_dir()
    paths = []
    if share_dir:
        paths.append(os.path.join(share_dir, "python"))
    paths.append(_script_dir())
    return _dedupe_paths(paths, keep=os.path.isdir)

def _read_file(path):
    try:
        with open(path, "r", encoding="utf-8") as f:
            return f.read()
    except OSError:
        return None

def _string_literal(node):
    if isinstance(node, ast.Constant) and isinstance(node.value, str):
        return node.value
    return None

def _command_name_from_call(node):
    if not isinstance(node, ast.Call):
        return None
    func = node.func
    if not isinstance(func, ast.Attribute) or func.attr != "__init__":
        return None

    value = func.value
    if (
        isinstance(value, ast.Call)
        and isinstance(value.func, ast.Name)
        and value.func.id == "super"
        and node.args
    ):
        return _string_literal(node.args[0])

    if (
        isinstance(value, ast.Attribute)
        and value.attr == "Command"
        and isinstance(value.value, ast.Name)
        and value.value.id == "gdb"
        and len(node.args) >= 2
    ):
        return _string_literal(node.args[1])

    return None

def _supported_commands_from_class(node):
    for child in node.body:
        if not isinstance(child, ast.Assign):
            continue
        names = []
        for target in child.targets:
            if isinstance(target, ast.Name):
                names.append(target.id)
            elif isinstance(target, ast.Attribute):
                names.append(target.attr)
        if "supported_commands" not in names:
            continue
        try:
            value = ast.literal_eval(child.value)
        except (SyntaxError, ValueError):
            continue
        if isinstance(value, (list, tuple)):
            return [item for item in value if isinstance(item, str)]
    return []

def _doc_summary(node):
    doc = ast.get_docstring(node) or ""
    for line in doc.splitlines():
        line = re.sub(r"\s+", " ", line.strip())
        if line:
            return line
    return ""

def _commands_from_tree(tree, path):
    commands = []
    for node in ast.walk(tree):
        if not isinstance(node, ast.ClassDef):
            continue
        supported_commands = _supported_commands_from_class(node)
        summary = _doc_summary(node)
        command_names = []
        for child in ast.walk(node):
            command_name = _command_name_from_call(child)
            if command_name:
                command_names.append(command_name)
        for command_name in command_names:
            commands.append(
                {
                    "command": command_name,
                    "class": node.name,
                    "file": os.path.basename(path),
                    "summary": summary,
                    "subcommands": supported_commands,
                }
            )
    return commands

# The command set is fixed once gdbscripts are sourced, so walk the Python
# source directories at most once per GDB session instead of on every prompt.
@functools.lru_cache(maxsize=1)
def _discover_gdbscript_commands():
    files = set()
    for python_dir in _python_dirs():
        try:
            names = os.listdir(python_dir)
        except OSError:
            continue
        for name in names:
            if not name.endswith(".py"):
                continue
            path = os.path.abspath(os.path.join(python_dir, name))
            if os.path.isfile(path):
                files.add(path)

    commands = []
    for path in files:
        text = _read_file(path)
        if text is None:
            continue
        try:
            tree = ast.parse(text, filename=path)
        except SyntaxError:
            continue
        commands.extend(_commands_from_tree(tree, path))

    unique = {}
    for command in commands:
        unique[command["command"]] = command
    return [unique[name] for name in sorted(unique)]

def _format_discovered_command_context(commands):
    if not commands:
        return "Discovered gdbscripts command context: no commands discovered."
    lines = ["Discovered gdbscripts command context:"]
    for item in commands:
        line = "- %s" % item["command"]
        if item.get("subcommands"):
            line += " [%s]" % ", ".join(item["subcommands"])
        if item.get("summary"):
            line += ": %s" % item["summary"]
        line += " (%s)" % item.get("file", "unknown source")
        lines.append(line)
    return "\n".join(lines)

def _runtime_context(skill_path):
    lines = ["Runtime context:"]
    if skill_path:
        lines.append("- Loaded skill path: %s" % skill_path)
    else:
        lines.append("- Loaded skill path: not found")

    share_dir = _nvgdb_dir()
    if share_dir:
        lines.append("- nvgdb_dir: %s" % share_dir)
        lines.append(
            "- nvgdb_dir is a Python global set by init.gdb, not a GDB "
            "setting; do not run 'show nvgdb_dir'."
        )
        lines.append(
            "- Installed init.gdb is expected at: %s"
            % os.path.join(share_dir, "init.gdb")
        )
    else:
        lines.append("- nvgdb_dir: not defined")
    return "\n".join(lines)

def _build_instructions():
    path, skill_context = _load_skill_context()
    runtime_context = _runtime_context(path)
    command_context = _format_discovered_command_context(
        _discover_gdbscript_commands()
    )
    if not skill_context:
        return "%s\n\n%s\n\n%s\n\n%s" % (
            SYSTEM_INSTRUCTIONS,
            runtime_context,
            command_context,
            "No gdbscripts skill context was found. Use generic GDB "
            "commands only unless the user supplies project-specific syntax."
        )
    return "%s\n\n%s\n\n%s\n\nLoaded gdbscripts skill context from %s:\n\n%s" % (
        SYSTEM_INSTRUCTIONS,
        runtime_context,
        command_context,
        path,
        skill_context,
    )

def _truncate(text, limit):
    if len(text) <= limit:
        return text, False
    suffix = "\n...[truncated %d chars]..." % (len(text) - limit)
    keep = max(0, limit - len(suffix))
    return text[:keep] + suffix, True

def _function_calls(response):
    return [item for item in response.output if item.type == "function_call"]

def _response_input_items(response):
    return [item for item in response.output if item.type in RESPONSE_INPUT_TYPES]

def _item_type(item):
    # input_items mixes plain dicts we build (user turns, function_call_output)
    # with OpenAI SDK objects from response.output, which expose .type but not
    # .get(); read the type safely regardless of representation.
    if isinstance(item, dict):
        return item.get("type")
    return getattr(item, "type", None)

def _tool_call_arguments(call):
    arguments = call.arguments
    if arguments is None:
        return {}, "Missing tool arguments."
    try:
        decoded = json.loads(arguments)
    except (ValueError, TypeError) as e:
        return {}, "Invalid JSON tool arguments: %s" % e
    if not isinstance(decoded, dict):
        return {}, "Tool arguments JSON must decode to an object, got %s." % (
            type(decoded).__name__
        )
    return decoded, None

class ai(gdb.Command):
    """
    Ask an OpenAI model a debugging question and let it inspect GDB state.

    Usage:
        ai [--verbose] [--clear] <prompt>
        ai --clear

    Environment:
        OPENAI_API_KEY              Required API key.
        OPENAI_MODEL                Model name.
        OPENAI_BASE_URL             API base URL. Defaults to https://inference-api.nvidia.com/v1/.
        GDB_AI_SKILL_PATH           Optional path to SKILL.md.
        GDB_AI_MAX_TOOL_CALLS       Max GDB commands per question. Defaults to 8.
        GDB_AI_MAX_OUTPUT_CHARS     Max captured output per command. Defaults to 12000.
        GDB_AI_MAX_HISTORY_ITEMS    Max prior conversation items to keep. Defaults to 40.
        GDB_AI_TIMEOUT_SECONDS      HTTPS timeout. Defaults to 60.

    ai asks for approval before running commands that may mutate debugger or
    target state.
    """

    def __init__(self):
        super(ai, self).__init__("ai", gdb.COMMAND_USER)
        self.history = []

    def complete(self, text, word):
        return gdb.COMPLETE_NONE

    def _parse_args(self, args):
        argv = gdb.string_to_argv(args)
        clear = False
        verbose = False
        prompt = []
        parsing_flags = True
        for arg in argv:
            if parsing_flags and arg == "--":
                parsing_flags = False
            elif parsing_flags and arg in ("-v", "--verbose"):
                verbose = True
            elif parsing_flags and arg == "--clear":
                clear = True
            else:
                prompt.append(arg)
        return clear, verbose, " ".join(prompt).strip()

    def _trim_history(self, input_items):
        max_items = _env_int("GDB_AI_MAX_HISTORY_ITEMS", DEFAULT_MAX_HISTORY_ITEMS)
        if max_items <= 0:
            self.history = []
        else:
            self.history = list(input_items[-max_items:])
            # Remove function_call_output items from the beginning of the history:
            # trimming may have dropped the function_call they pair with, and the
            # API rejects a function_call_output without its preceding call.
            while (len(self.history) > 0 and
                _item_type(self.history[0]) == "function_call_output"):
                self.history = self.history[1:]

    def _create_response(self, input_items, instructions):
        api_key = os.environ.get("OPENAI_API_KEY")
        if not api_key:
            raise gdb.GdbError(
                "OPENAI_API_KEY is not set. Export it before launching GDB."
            )

        base_url = os.environ.get("OPENAI_BASE_URL", DEFAULT_BASE_URL).rstrip("/")
        timeout = _env_int("GDB_AI_TIMEOUT_SECONDS", DEFAULT_TIMEOUT_SECONDS)
        client = OpenAI(
            api_key=api_key,
            base_url=base_url,
            timeout=timeout,
        )

        try:
            response = client.responses.create(
                model=os.environ.get("OPENAI_MODEL", DEFAULT_MODEL),
                instructions=instructions,
                tools=[RUN_GDB_COMMAND_TOOL],
                input=input_items,
                parallel_tool_calls=False,
                store=False,
            )
            return response
        except OpenAIError as e:
            raise gdb.GdbError("OpenAI Responses API request failed: %s" % e)

    def _run_gdb_command(self, command, reason, verbose):
        command = command.strip()
        max_output = _env_int("GDB_AI_MAX_OUTPUT_CHARS", DEFAULT_MAX_OUTPUT_CHARS)
        if "\n" in command or "\r" in command:
            return json.dumps(
                {
                    "command": command,
                    "ok": False,
                    "rejected": True,
                    "error": (
                        "run_gdb_command only accepts one non-interactive "
                        "single-line GDB command. Do not send multi-line "
                        "python, source, command, or pagination-driven blocks."
                    ),
                }
            )
        approved = True
        if not _is_command_safe(command):
            approved = _approved_by_user(command, reason)
            if not approved:
                return json.dumps(
                    {
                        "command": command,
                        "ok": False,
                        "approved": False,
                        "output": (
                            "The user did not approve running this command. "
                            "Try a read-only command or answer without it."
                        ),
                    }
                )

        gdb.write("ai: running: %s\n" % command)
        try:
            output = gdb.execute(command, from_tty=False, to_string=True)
            output, truncated = _truncate(output, max_output)
            if verbose and output:
                gdb.write(output)
                if not output.endswith("\n"):
                    gdb.write("\n")
            return json.dumps(
                {
                    "command": command,
                    "ok": True,
                    "approved": approved,
                    "truncated": truncated,
                    "output": output,
                }
            )
        except Exception as e:
            return json.dumps(
                {
                    "command": command,
                    "ok": False,
                    "exception_type": type(e).__name__,
                    "error": str(e),
                }
            )

    def _dispatch_tool_call(self, call, verbose):
        """Run one model tool call and return its function_call_output item."""
        if call.name != "run_gdb_command":
            result = json.dumps(
                {"ok": False, "error": "Unknown tool %s" % call.name}
            )
        else:
            call_args, arguments_error = _tool_call_arguments(call)
            if arguments_error:
                result = json.dumps({"ok": False, "error": arguments_error})
            else:
                command = call_args.get("command")
                reason = call_args.get("reason", "")
                if not isinstance(command, str):
                    result = json.dumps(
                        {"ok": False, "error": "Missing string argument: command"}
                    )
                elif not isinstance(reason, str):
                    result = json.dumps(
                        {"ok": False, "error": "Missing string argument: reason"}
                    )
                else:
                    result = self._run_gdb_command(command, reason, verbose)

        return {
            "type": "function_call_output",
            "call_id": call.call_id,
            "output": result,
        }

    def invoke(self, args, from_tty):
        self.dont_repeat()
        clear, verbose, prompt = self._parse_args(args)
        if clear:
            self.history = []
            if not prompt:
                gdb.write("ai: conversation history cleared.\n")
                return
        if not prompt:
            raise gdb.GdbError("The ai command needs a prompt, try 'help ai'.")

        max_tool_calls = _env_int("GDB_AI_MAX_TOOL_CALLS", DEFAULT_MAX_TOOL_CALLS)
        instructions = _build_instructions()
        input_items = list(self.history)
        input_items.append({"role": "user", "content": prompt})
        final_retry = False

        for _ in range(max_tool_calls + 1):
            response = self._create_response(input_items, instructions)
            input_items += _response_input_items(response)

            calls = _function_calls(response)
            if not calls:
                text = (response.output_text or "").strip()
                if text:
                    gdb.write(text)
                    if not text.endswith("\n"):
                        gdb.write("\n")
                    self._trim_history(input_items)
                else:
                    if not final_retry:
                        final_retry = True
                        input_items.append(
                            {
                                "role": "user",
                                "content": (
                                    "No final text was returned. Provide a "
                                    "concise final answer based on the tool "
                                    "outputs. If you cannot answer, say what "
                                    "targeted command should be tried next."
                                ),
                            }
                        )
                        continue
                    gdb.write("ai: model returned no text response.\n")
                    self._trim_history(input_items)
                return

            if len(input_items) > 200:
                raise gdb.GdbError("ai internal conversation grew unexpectedly.")

            for call in calls:
                input_items.append(self._dispatch_tool_call(call, verbose))

        raise gdb.GdbError(
            "ai stopped after %d tool call round(s). Try a narrower prompt."
            % max_tool_calls
        )

ai()

