# This file implement the core command

import apb
import openocd
import re
import gdb
import spr

_CORE_COMMAND_DOC_PUBLIC = """
    The core command is used to select the active core being debugged, it will
    select the proper OpenOCD target, APB offset, bus etc... Note that in SMT
    cores, OpenOCD and GDB still see each thread as a separate core. Variants
    are:
    core [ <name> ]
        Without argument this will display the active core, otherwise:
        <name>: make core named <name> the active core.
    core dummy <core>[.<thread>]:
        Switch to a core with the geometry specified even if it does not exist.
            In this mode the GDB state will not be updated and only the commands
            that use apb will work properly.
            <thread> is required on platforms that support them.
    core list:
        List all the core that are valid (some cores may be floorswept).
    core attach { yes | no }:
        Select whether a core change should also affect the
            runtime state of GDB (stop the core and fetch its state).
    core configure:
        Without any parameter it displays the current configuration, otherwise:
        configure platform <target_name>: tell the core command the target's name.
        configure apb <apb_base> <apb_offset>: tell the core command
            the base address of the first core on the APB bus, the offset of each
            core after.
        configure chiplet <cores_per_chiplet> <chiplet_offset>: tell the core
            command the number of cores per chiplet and the offset between chiplets
            in main memory.
    """

# Core command
class core(gdb.Command):
    __doc__ = _CORE_COMMAND_DOC_PUBLIC
    current_core = None
    cores_list = None
    state_changed = True
    supported_configure_commands = ['platform', 'apb', 'chiplet']
    config = {
        'platform_name': None,
        'apb_base': 0,
        'core_offset': 0,
        'apb_name': None,
        'axi_name': None,
        'mmio_apb_base': 0,
        'threads_per_core': 1,
        'cores_per_chiplet': 1000, # a ridiculous number
        'max_chiplets': 1,
        'ccplex_mode': True,
        'attach_mode': True,
        'chiplet_offset': 0,
        'dummy_cores_mode': False,
    }

    def __init__(self):
        super(core, self).__init__("core", gdb.COMMAND_SUPPORT)

    def complete(self, text, word):
        textv = gdb.string_to_argv(text)
        supported_commands = ['list', 'attach', 'configure', 'dummy']
        if self.cores_list != None:
            supported_commands += [c['name'] for c in self.cores_list]
        if len(textv) == 0:
            return supported_commands
        elif textv[0] == 'attach':
            if len(textv) == 1:
                return ['on', 'off']
            elif (len(textv) == 2) and (textv[1] == word):
                return [s for s in ['on', 'off'] if s.startswith(word)]
            else:
                return gdb.COMPLETE_NONE
        elif textv[0] == 'configure':
            if len(textv) == 1:
                return self.supported_configure_commands
            elif (len(textv) == 2) and (textv[1] == word):
                return [s for s in self.supported_configure_commands if s.startswith(word)]
            else:
                return gdb.COMPLETE_NONE
        elif (len(textv) == 1) and (textv[0] == word):
            return [s for s in supported_commands if s.startswith(word)]
        else:
            return gdb.COMPLETE_NONE

    def fill_cores_list(self):
        clist = []

        # This can take a very long time, do it only if GDB state has
        # meaningfully changed (has been resumed)
        if not self.state_changed:
            return

        targets = openocd.get_targets(True)
        if self.config['attach_mode']:
            gdbthreads = gdb.execute("info threads", False, True).split('\n')
        else:
            gdbthreads = None
        # Generate a fake list if we are in dummy core mode
        if self.config['dummy_cores_mode']:
            # We are going to modify some fields
            oocd_targets = targets
            targets = []
            if self.config['ccplex_mode']:
                for c in range(self.config['cores_per_chiplet']*self.config['max_chiplets']):
                    if self.config['threads_per_core'] > 1:
                        for th in range(self.config['threads_per_core']):
                            m = None
                            for t in oocd_targets:
                                m = re.match(r'.*\.core%dt%d$' % (c, th), t['name'])
                                if m != None:
                                    targets.append(t)
                                    break
                            if m == None:
                                targets.append({'name': "dummy.core%dt%d" % (c, th), 'type': "dummy", 'state': "unknown"})
                    else:
                        m = None
                        for t in oocd_targets:
                            m = re.match(r'.*\.core%d$' % c, t['name'])
                            if m != None:
                                targets.append(t)
                                break
                        if m == None:
                            targets.append({'name': "dummy.core%d" % c, 'type': "dummy", 'state': "unknown"})
            else:
                raise gdb.GdbError("INTERNAL ERROR: Unsupported mode.")

        first = True
        for t in targets:
            if self.config['ccplex_mode']:
                m = re.match(r'.*\.core([0-9]+)', t['name'])
            else:
                raise gdb.GdbError("INTERNAL ERROR: Unsupported mode.")
            if m != None:
                entry = {'state': t['state'], 'type': t['type'], 'core': int(m.group(1), 0)}
                if not t['name'].startswith("dummy."):
                    entry['target'] = t['name']
                if self.config['ccplex_mode']:
                    entry['chiplet'] = int(m.group(1), 0) // self.config['cores_per_chiplet']
                    entry['core_in_chiplet'] = int(m.group(1), 0) % self.config['cores_per_chiplet']
                    m = re.match(r'.*\.core[0-9]+t([0-9]+)', t['name'])
                    if m != None:
                        entry['thread'] = int(m.group(1), 0)
                        entry['name'] = "core%d.thread%d" % (entry['core'], entry['thread'])
                    else:
                        entry['name'] = "core%d" % entry['core']
                else:
                    raise gdb.GdbError("INTERNAL ERROR: Unsupported mode.")
                if gdbthreads != None:
                    for line in gdbthreads:
                        m = re.match(r'^[*\s]+(\d+)\s.*Name: %s,.*' % t['name'], line)
                        if m != None:
                            entry['tid'] = int(m.group(1), 0)
                            break
                clist.append(entry)
                if first:
                    # This is the current active core
                    if self.current_core == None:
                        self.activate_core(entry, silent = True)
                    first = False
        self.cores_list = clist
        self.state_changed = False

    def activate_core(self, core, quick=False, silent=False):
        if self.config['platform_name'] == None:
            raise gdb.GdbError("INTERNAL ERROR: Platform name not set.")
        # Fetch targets list which we will use all over the place
        targets = openocd.get_targets()
        if (core['type'] != 'dummy'):
            if 'target' not in core:
                raise gdb.GdbError("INTERNAL ERROR: non-dummy core without an OpenOCD target.")
            # Set the active OpenOCD target to match
            openocd.select_target(core['target'])
        if 'thread' in core:
            gdb.execute("spr set thread %d" % (core['thread']), to_string=silent)
        # Configure the APB command to use OpenOCD
        if self.config['apb_name'] != None:
            apb_bus_name = self.config['apb_name'].replace("<chiplet>", str(core['chiplet']))
            apb_addr = 0
            if (apb_bus_name in targets) and (apb_bus_name != self.config['apb_name']):
                # If user did specify and it exists we should use a chiplet specific APB
                gdb.execute("apb set access openocd %s" % apb_bus_name, to_string=silent)
            else:
                # If the apb bus for a chiplet does not exist or user hard-coded the chiplet
                # then we use MMIO since we don't know what the APB can reach.
                gdb.execute("apb set access openocd %s 0x%x" % (self.config['axi_name'].replace("<chiplet>", "0"), self.config['mmio_apb_base']), to_string=silent)
                apb_addr += core['chiplet']*self.config['chiplet_offset']
            # Set the APB bus base
            if self.config['ccplex_mode']:
                apb_addr += self.config['apb_base']+self.config['core_offset']*(core['core_in_chiplet'])
            gdb.execute("apb set base 0x%x" % apb_addr, to_string=silent)
            if 'thread' in core:
                gdb.execute("apb set smt %d" % (core['thread']), to_string=silent)
        # If attach is on, switch the active thread
        if self.config['attach_mode'] and not quick:
            if 'tid' in core:
                gdb.execute("thread %d" % core['tid'], to_string=silent)
            elif not silent:
                print("WARNING: core %s not attached to a GDB thread." % core['name'])
        self.current_core = core

    def activate_dummy_core(self, core, thread):
        core = int(core, 0) if isinstance(core, str) else int(core)
        if thread is not None:
            thread = int(thread, 0) if isinstance(thread, str) else int(thread)

        core_obj = self.current_core.copy()
        if 'tid' in core_obj:
            # We do not want activate_core to mess with GDB state
            del core_obj['tid']
        core_obj['core'] = core
        if self.config['ccplex_mode']:
            core_obj['chiplet'] = core // self.config['cores_per_chiplet']
            core_obj['core_in_chiplet'] = core % self.config['cores_per_chiplet']
        else:
            raise gdb.GdbError("INTERNAL ERROR: Unsupported mode.")
        if thread != None:
            core_obj['name'] = "dummy core %d.%d" % (core, thread)
            core_obj['thread'] = thread
        else:
            core_obj['name'] = "dummy core %d" % core
        core_obj['type'] = 'dummy'
        self.activate_core(core_obj)

    def invoke(self, args, from_tty):
        self.dont_repeat()
        argv = gdb.string_to_argv(args)
        if len(argv) == 0:
            # If we are not attached current_core is bogus or None
            openocd.check_attached()
            if self.current_core == None:
                print("No core selected.")
            else:
                print(self.current_core['name'])
                gdb.add_history(self.current_core['name'])
        elif argv[0] == 'list':
            # We cannot switch core if we are not attached
            openocd.check_attached()
            # Always refresh the list
            self.fill_cores_list()
            print("Target has %d cores:" % len(self.cores_list))
            for c in self.cores_list:
                if 'tid' in c:
                    gdb_info = "GDB thread %d" % c['tid']
                else:
                    gdb_info = "Not attached in GDB"
                if 'target' in c:
                    if 'thread' in c:
                        print("%s: %s (OOCD target %s - %s - Thread %d Core %d in chiplet %d)" % (c['name'], c['state'], c['target'], gdb_info, c['thread'], c['core_in_chiplet'], c['chiplet']))
                    else:
                        print("%s: %s (OOCD target %s - %s - Core %d in chiplet %d)" % (c['name'], c['state'], c['target'], gdb_info, c['core_in_chiplet'], c['chiplet']))
                else:
                    print("%s: %s (No OOCD target (dummy core) - %s - Core %d in chiplet %d)" % (c['name'], c['state'], gdb_info, c['core_in_chiplet'], c['chiplet']))
        elif argv[0] == 'attach':
            if len(argv) == 1:
                if self.config['attach_mode']:
                    print("The core command will attempt to attach to the active thread.")
                else:
                    print("The core command will not attempt to attach to the active thread.")
            elif len(argv) != 2:
                raise gdb.GdbError("The attach subcommand expects one argument. Try 'help core'.")
            elif argv[1] == 'on':
                self.config['attach_mode'] = True
            elif argv[1] == 'off':
                self.config['attach_mode'] = False
            else:
                raise gdb.GdbError("Invalid argument '%s' to the attach subcommand. Try 'help core'." % argv[1])
        elif argv[0] == 'configure':
            if len(argv) == 1:
                if self.config['platform_name'] == None:
                    print("Core command not configured to support a platform yet, run 'core configure ...' first.")
                else:
                    print("Current configuration:")
                    print("Platform: %s." % (self.config['platform_name']))
                    print("APB: base at address 0x%08x, core N at N*0x%x using target %s." % (self.config['apb_base'], self.config['core_offset'], self.config['apb_name']))
                    print("APB offset in MMIO 0x%x." % (self.config['mmio_apb_base']))
                    print("Chiplet: %d cores per chiplet, chiplet N at N*0x%x in memory map." % (self.config['cores_per_chiplet'], self.config['chiplet_offset']))
            elif argv[1] == 'platform':
                if len(argv) == 2:
                    print("Current platform configuration: named %s." % (self.config['apb_name']))
                else:
                    if len(argv) != 3:
                        raise gdb.GdbError("The configure platform subcommand expects one argument. Try 'help core'.")
                    self.config['platform_name'] = argv[2]
            elif argv[1] == 'apb':
                if len(argv) == 2:
                    print("Current APB configuration: base at address 0x%08x, core N at N*0x%x using target %s." % (self.config['apb_base'], self.config['core_offset'], self.config['apb_name']))
                else:
                    if len(argv) != 4:
                        raise gdb.GdbError("The configure apb subcommand expects two arguments. Try 'help core'.")
                    try:
                        self.config['apb_base'] = int(argv[2], 0)
                        self.config['core_offset'] = int(argv[3], 0)
                        self.config['apb_name'] = "%s.<chiplet>.apb" % self.config['platform_name']
                    except:
                        raise gdb.GdbError("Invalid arguments '%s' to configure %s subcommand. Try 'help core'." % (' '.join(argv[2:]), argv[1]))
            elif argv[1] == 'chiplet':
                if len(argv) == 2:
                    print("Current chiplet configuration: %d cores per chiplet, chiplet N at N*0x%x in memory map." % (self.config['cores_per_chiplet'], self.config['chiplet_offset']))
                else:
                    if len(argv) != 4:
                        raise gdb.GdbError("The configure chiplet subcommand expects two arguments. Try 'help core'.")
                    try:
                        self.config['cores_per_chiplet'] = int(argv[2], 0)
                        self.config['chiplet_offset'] = int(argv[3], 0)
                    except:
                        raise gdb.GdbError("Invalid arguments '%s' to configure %s subcommand. Try 'help core'." % (' '.join(argv[2:]), argv[1]))
            else:
                raise gdb.GdbError("Invalid argument '%s' to the configure subcommand. Try 'help core'." % argv[1])
        elif argv[0] == 'dummy':
            if len(argv) != 2:
                raise gdb.GdbError("Invalid argument '%s' to dummy subcommand. Try 'help core'." % (' '.join(argv[1:])))
            # We cannot switch core if we are not attached
            openocd.check_attached()
            geometry = argv[1].split('.')
            core = geometry[0]
            thread = None
            if 'tid' in self.current_core:
                if len(geometry) != 2:
                    raise gdb.GdbError("Invalid geometry '%s' for platform %s." % (argv[1], self.config['platform_name']))
                thread = geometry[1]
            elif len(geometry) != 1:
                raise gdb.GdbError("Invalid geometry '%s' for platform %s." % (argv[1], self.config['platform_name']))
            self.activate_dummy_core(core, thread)
            print("Switched to active core %s." % self.current_core['name'])
        else:
            # We cannot switch core if we are not attached
            openocd.check_attached()
            # Set the core being debugged
            if self.cores_list == None:
                self.fill_cores_list()
            core_found = [ ce for ce in self.cores_list if ce['name'] == argv[0] ]
            if len(core_found) == 0:
                raise gdb.GdbError("Core %s not found, try 'core list'." % argv[0])
            elif len(core_found) != 1:
                raise gdb.GdbError("INTERNAL ERROR: multiple core with id %s found." % argv[0])
            self.activate_core(core_found[0])
            print("Switched to active core %s." % self.current_core['name'])

    def configure(self, config_obj: dict):
        """
        External Python API: use with core.core_control object.
        Configure the behavior of the core command, this can be used to avoid calling core configure * subcommands.
        The fields that can be passed in config_obj are:
        - platform_name: (str) the name of the platform
        - apb_base: (int) the ccplex cores base address of the APB bus
        - core_offset: (int) the offset of each core after that
        - apb_name: (str) the name of the APB bus
        - axi_name: (str) the name of the AXI bus
        - mmio_apb_base: (int) the APB base on MMIO (APB address 0x0)
        - threads_per_core: (int) number of threads per core (if applicable, 1
         otherwise)
        - cores_per_chiplet: (int) the number of cores per chiplet
        - max_chiplets: (int) maximum number of chiplets possible
        - attach_mode: (bool) whether to attempt to attach to the active thread
        - chiplet_offset: (int) the offset between chiplets in main memory
        - dummy_cores_mode: (bool) if set the cores returned by OpenOCD will be
         ignored, instead we will generate a list of cores for a perfect part.
        """
        self.config.update(config_obj)
        # Best to have the core module handle naming:
        if 'apb_name' not in config_obj:
            self.config['apb_name'] = "%s.<chiplet>.apb" % self.config['platform_name']
        if 'axi_name' not in config_obj:
            self.config['axi_name'] = "%s.<chiplet>.axi" % self.config['platform_name']
        # We need to refresh the state. Drop the active core as well: callers
        # reload the register databases right after configuring us, which
        # resets their SMT selection, and only activate_core() restores it.
        self.state_changed = True
        self.current_core = None

    def for_each_core(self, func):
        """External Python API: use with core.core_control object.
        Call func for each core.
        Func should take one argument, the core dictionary which include the following fields:
        - target: (str) the name of the OpenOCD target
        - state: (str) the state of the core
        - core: (int) the core number
        - chiplet: (int) the chiplet number
        - core_in_chiplet: (int) the core number in the chiplet
        - thread: (int) the thread number if applicable
        - name: (str) the name of the core
        - tid: (int) the thread ID in GDB if applicable
        """
        current_core = self.current_core
        for c in self.cores_list:
            self.activate_core(c, quick=True, silent=True)
            func(c)
        self.activate_core(current_core, quick=False, silent=True)

    def get_active_core(self):
        """External Python API: use with core.core_control object.
        Return the active core as a dictionary with the same fields as the core dictionary:
        - target: (str) the name of the OpenOCD target
        - state: (str) the state of the core
        - core: (int) the core number
        - chiplet: (int) the chiplet number
        - core_in_chiplet: (int) the core number in the chiplet
        - thread: (int) the thread number if applicable
        - name: (str) the name of the core
        - tid: (int) the thread ID in GDB if applicable
        """
        return self.current_core

def core_cont_handler(event):
    core_control.state_changed = True

core_control = core()

gdb.events.cont.connect(core_cont_handler)

