import gdb
import ext_spr_spec_db
import re
import openocd

class apb(gdb.Command):
    """
    The apb command allows you to read, write and get more info about APB
    registers. It supports the following subcommands:
    set <parameter> [ <args> ]
        The following variants are supported:
        base [ <addr> ]: set the base APB offset to append to any APB register
         operation. <addr> must be a number, if not specified the current
         value is displayed.
        access core <base> | openocd [ <target> [ <base> ] ]: configure how APB accesses
         should be made. In core mode the APB access is made by the core
         in Debug State by appending <base> to the register address, this
         should work with any target but may be subject to virtual address
         translation. In openocd mode the special monitor command is used to
         communicate directly with an OpenOCD gdbserver to request an access
         to be made to target <target>. If no target is specified the command
         will try to detect which target to use and if it cannot display the
         valid targets reported by OpenOCD. This version can also talke a base
         which is applied to all accesses (including absolute accesses).
        smt off | <n>: on multi-threaded system this can be used to control
         how core APB registers should be displayed: if off then the core will
         show all threads apertures differentiating with an index after the name,
         otherwise only the apertures relevant to thread <n> or global to the
         core will be displayed.
        debug on | off: enable or disable extra debug messages.
    read [/x] [/n] [/32] <reg_name> | [/a] <reg_addr> | <reg_name>.<field_name>
        Read the specified register from the attached target and return
         its content. This command can only be used if a running target
         is attached. If /a is specified <reg_addr> is treated as an absolute
         address rather than relative to the base address.
        For the <reg_name> variant by default a dictionary of
         the fields in the register will be returned. If /n is specified
         then the value will be returned instead.
        For the <reg_addr> variant the value of the register is returned
         and /n has no effect.
        For the <reg_name>.<field_name> variant the value of the field is
         returned and /n has no effect.
        For all variants if /x is specified the number are hex numbers
        instead of decimals.
        If /32 is specified the register is read as 32 bits no matter its size.
    write [/32] [/q] <reg_name> | [/a] <reg_addr> | <reg_name>.<field_name> = <value>
        Write <value> to the specified register, if a field is specified
         then a read-modify-write will be performed. <value> can be a
         dictionary (as retruned by read command) or a
         number that fits in the register or field. This command can
         only be used if a running target is attached. If /a is specified
         <reg_addr> is treated as an absolute address rather than relative
         to the base address.
        If /32 is specified the register is written as 32 bits no matter its size.
        Option /q will not print the value written, option /x will print it in
        hex rather than decimal.
    info [/s] <pattern> | <reg_name> | <reg_addr>
        Return the name, address, size and fields of all registers
         matching the specified pattern, name or address. If /s is specified
         then only the name (<pattern> or <reg_addr> variants) or address
         (<reg_name> variant) is returned.
    load <yml_db>
        Load the registers description from a YAML database specified by
         <yml_db>. This is necessary before using the info command or
         using the <reg_name>* variants of the other commands.
    """
    supported_commands = ['read', 'write', 'info', 'load', 'set']
    loaded_regspec = None
    regspec = None
    base = 0x0
    access_mode = 'core'
    access_arg = 0x0
    smt_thread = -1 # SMT mode disabled by default
    smt_nthreads = -1 # SMT mode support unknown
    debug = False

    def __init__(self):
        super(apb, self).__init__("apb", gdb.COMMAND_DATA)

    def lookup_reg_by_addr(self, addr):
        """
        Return the register entry that match <addr>, where <addr> is relative to
        self.base. This API assumes only one match is possible.
        """
        for component in self.regspec:
            if 'registers' in self.regspec[component]:
                for regname, reg in self.regspec[component]['registers'].items():
                    if reg['address'] == addr:
                        return reg
        return None

    def print_register(self, reg, header = ''):
        print(f"{header}Name: {reg['name']}")
        print(f"{header}Description: {reg['title']}")
        if 'thread' in reg:
            print(f"{header}Thread: {reg['thread']}")
        print(f"{header}Access: {reg['access']}")
        print(f"{header}Size: {reg['width']} bits")
        addr = reg['address']+self.base
        print(f"{header}Address: 0x{addr:x}")
        if 'fields' in reg:
            print(f"{header}Fields ({len(reg['fields'])}):")
            for field in reg['fields']:
                print("%s\t[%s:%s]: %s (reset=%s, access=%s)." % (header, field['bit_hi'], field['bit_lo'], field['name'], field['reset_value'], field['access']))

    def read_apb(self, addr, size, absolute_addr = False):
        """Read a register on the APB bus, sizes supported are 32 and 64."""
        if not absolute_addr:
            addr += self.base
        if self.access_mode == 'core':
            if size == 32:
                size_attr = 'w'
            elif size == 64: 
                size_attr = 'g'
            else:
                raise gdb.GdbError("APB read from 0x%08x: accesses of size %d not supported in %s mode." % (addr, size, self.access_mode))
            addr += self.access_arg
            resp = gdb.execute("x/1u%s %u" % (size_attr, addr), False, True)
            try:
                access = int(resp)
            except:
                raise gdb.GdbError("APB read of size %d at 0x%08x using %s mode failed: %s." % (size, addr, self.access_mode, resp))
        elif self.access_mode == 'openocd':
            old_target = openocd.select_target(self.access_arg[0])
            addr += self.access_arg[1]
            if size == 64:
                access_lo = openocd.read_memory(addr, 32)
                access_hi = openocd.read_memory(addr+4, 32)
                if (access_lo == None) or (access_hi == None):
                    access = None
                else:
                    access = (access_hi << 32) | access_lo
            elif size == 32:
                access = openocd.read_memory(addr, 32)
            else:
                raise gdb.GdbError("APB read of size %d using %s mode are not supported." % (size, self.access_mode))
            openocd.select_target(old_target)
        else:
            raise gdb.GdbError("INTERNAL ERROR: APB read from 0x%08x: access mode %s not supported." % (addr, self.access_mode))
        if self.debug:
            if access != None:
                print("APB: 0x%08x => 0x%08x (%db/%s)." % (addr, access, size, self.access_mode))
            else:
                print("APB: 0x%08x => UNRESOLVED YET (%db/%s)." % (addr, size, self.access_mode))
        return access

    def write_apb(self, addr, size, value, absolute_addr = False):
        """Write a register on the APB bus, sizes supported are 32 and 64."""
        if not absolute_addr:
            addr += self.base
        if self.access_mode == 'core':
            if size == 32:
                access_type = 'unsigned int'
            elif size == 64:
                access_type = 'unsigned long long'
            else:
                raise gdb.GdbError("APB write to 0x%08x: accesses of size %d not supported in %s mode." % (addr, size, self.access_mode))
            addr += self.access_arg
            try:
                gdb.execute("set *{%s}0x%x=0x%x" % (access_type, addr, value), False, True)
            except:
                raise gdb.GdbError("APB write of size %d to 0x%08x using %s mode failed" % (size, addr, self.access_mode))
        elif self.access_mode == 'openocd':
            old_target = openocd.select_target(self.access_arg[0])
            addr += self.access_arg[1]
            if size == 64:
                openocd.write_memory(addr, 32, value & 0xffffffff)
                openocd.write_memory(addr+4, 32, value >> 32)
            elif size == 32:
                openocd.write_memory(addr, 32, value)
            else:
                raise gdb.GdbError("APB write of size %d using %s mode are not supported." % (size, self.access_mode))
            openocd.select_target(old_target)
        else:
            raise gdb.GdbError("INTERNAL ERROR: APB write to 0x%08x: access mode %s not supported." % (addr, self.access_mode))
        if self.debug:
            print("APB: 0x%08x <= 0x%08x (%db/%s)." % (addr, value, size, self.access_mode))
        return value

    def complete_helper_commands(self, textv, word, commands):
        """Helper function for code that would otherwise be duplicated"""
        if len(textv) == 0:
            return commands
        elif (len(textv) == 1) and (textv[0] == word):
                return [s for s in commands if s.startswith(word)]
        else:
            return None

    def complete(self, text, word):
        textv = gdb.string_to_argv(text)
        # First we ignore all optional arguments
        for arg in list(textv):
            if arg.startswith('/'):
                textv.remove(arg)
        # If completion is on command type return the intersect of word
        # and the supported commands.
        opts = self.complete_helper_commands(textv, word, self.supported_commands)
        if opts != None:
            return opts
        elif textv[0] == 'load':
            # load is looking for a file, use GDB's handler for that
            if len(textv) <= 2:
                return gdb.COMPLETE_FILENAME
            else:
                return gdb.COMPLETE_NONE
        elif textv[0] == 'set':
            # Set only support a subset of subcommands
            opts = self.complete_helper_commands(textv[1:], word, ['base', 'access', 'smt', 'debug'])
            if opts != None:
                return opts
            elif textv[1] == 'access':
                opts = self.complete_helper_commands(textv[2:], word, ['core', 'openocd'])
                if opts != None:
                    return opts
                else:
                    return gdb.COMPLETE_NONE
            elif textv[1] == 'smt':
                smt_list = ['off']
                # Add all threads to the list of valid options
                if self.smt_nthreads > 0:
                    for n in range(self.smt_nthreads):
                        smt_list.append("%d" % n)
                opts = self.complete_helper_commands(textv[2:], word, smt_list)
                if opts != None:
                    return opts
                else:
                    return gdb.COMPLETE_NONE
            elif textv[1] == 'debug':
                opts = self.complete_helper_commands(textv[2:], word, ['on', 'off'])
                if opts != None:
                    return opts
                else:
                    return gdb.COMPLETE_NONE
            else:
                # No completion for this subcommand's arguments
                return gdb.COMPLETE_NONE
        elif not textv[0] in self.supported_commands:
            # the command mentioned is not supported
            return gdb.COMPLETE_NONE
        # If we get here we are looking for a register or register+field.
        cmd = textv[0]
        # Now the register should be in position 2, check this is what the
        # user is trying to complete, otherwise return as we cannot complete
        # other parameters.
        if len(textv) > 2:
            return gdb.COMPLETE_NONE
        # If this is a number we cannot complete but don't need a database
        try:
            v = int(textv[1], 0)
            return gdb.COMPLETE_NONE
        except:
            pass
        # Now we can search but we need a database
        if self.regspec == None:
            return gdb.COMPLETE_NONE
        if len(textv) < 2:
            # User has not yet typed any start of a name
            return list(self.regspec.keys())
        # Now we know textv[1] exists
        regname = textv[1].split('.')
        nextname = (word == '') and not textv[1].endswith('.')
        if len(regname) == 1:
            # Search for components
            choices = [k for k in self.regspec if k.startswith(regname[0])]
            if (len(choices) == 1) \
                    and ('registers' in self.regspec[choices[0]]) \
                    and (len(self.regspec[choices[0]]['registers']) > 0):
                # We found one match and it contains registers, offer the
                # list of registers to keep completion going.
                return ["%s.%s" % (choices[0], k) for k in self.regspec[choices[0]]['registers']]
            else:
                return choices
        if not regname[0] in self.regspec:
            # Component name is bogus
            return gdb.COMPLETE_NONE
        if not 'registers' in self.regspec[regname[0]]:
            # Component does not contain registers
            return gdb.COMPLETE_NONE
        if (len(regname) == 2) and not nextname:
            # Search for registers
            regs = [k for k in self.regspec[regname[0]]['registers'] if k.startswith(regname[1])]
            if (len(regs) == 1) and ('fields' in self.regspec[regname[0]]['registers'][regs[0]]) and (cmd != 'info'):
                regs.append(regs[0] + '.')
            return regs
        elif not regname[1] in self.regspec[regname[0]]['registers']:
            # Bogus register
            return gdb.COMPLETE_NONE
        if (len(regname) == 3) and not nextname:
            if not 'fields' in self.regspec[regname[0]]['registers'][regname[1]] or (cmd == 'info'):
                return gdb.COMPLETE_NONE
            flist = [k['name'] for k in self.regspec[regname[0]]['registers'][regname[1]]['fields']]
            flist.append('flat')
            return [l for l in flist if l.startswith(textv[1].split('.')[2])]
        # Bogus name
        return gdb.COMPLETE_NONE

    def cmd_read(self, argv, from_tty):
        # parse options first and remove them from argv
        options = []
        # We iterate over a copy of argv since we are modifying it on the fly
        for arg in list(argv):
            if arg.startswith('/'):
                options.append(arg[1:])
                argv.remove(arg)
        if len(argv) != 2:
            raise gdb.GdbError("Invalid syntax for subcommand '%s' (expected a single string or number, got '%s')." % (argv[0], ' '.join(argv[1:])))
        # Check if the argument is a string or a number
        try:
            reg_addr = int(argv[1], 0)
            reg_byname = False
        except:
            # Not a number
            reg_addr = 0
            reg_byname = True
            pass
        opt_hex = False
        opt_num = False
        opt_abs = False
        opt_32 = False
        for opt in options:
            if opt == 'x':
                opt_hex = True
            elif opt == 'n':
                opt_num = True
            elif opt == 'a':
                opt_abs = True
            elif opt == '32':
                opt_32 = True
            else:
                raise gdb.GdbError("Unknown option '/%s' to 'apb read' command. Try 'help apb'." % opt)
        if reg_byname:
            if self.regspec == None:
                raise gdb.GdbError("To refer to a register by name you must have loaded a database with 'apb load'. Try 'help apb'.")
            if opt_abs:
                raise gdb.GdbError("The /a option is not supported for the <reg_name> variant of the 'apb read' command. Try 'help apb'.")
            reg_name_list = argv[1].split('.')
            if len(reg_name_list) > 2:
                reg_name = '.'.join(reg_name_list[0:2])
                # Note that there should not be any dot in the field name, this
                # is here to make sure if an invalid name is given a piece of it
                # won't be ignored.
                reg_field_name = '.'.join(reg_name_list[2:])
            else:
                reg_name = '.'.join(reg_name_list)
                reg_field_name = None
            reg = self.lookup_reg_by_name(reg_name)
            if reg == None:
                raise gdb.GdbError("No register named %s found, try 'apb info %s'." % (reg_name, reg_name))
            reg_field = None
            if (reg_field_name != None) and (reg_field_name != 'flat'):
                for field in reg['fields']:
                    if field['name'] == reg_field_name:
                        reg_field = field
                if reg_field == None:
                    raise gdb.GdbError("No field named %s in register %s." % (reg_field_name, reg_name))
            reg_addr = reg['address']
        elif self.regspec != None:
            reg = self.lookup_reg_by_addr(reg_addr)
            reg_field = None
        else:
            # If no db is loaded we still support accessing APB we just will
            # not be able to decode the register.
            reg = None
            reg_field = None
        if opt_32:
            reg_size = 32
        elif reg != None:
            reg_size = reg['width']
        else:
            # Assume register is 32b
            reg_size = 32
        reg_data = self.read_apb(reg_addr, reg_size, opt_abs)
        if (reg != None) and (reg_field == None) and (not opt_num):
            v = self.encode_apb_value(reg, reg_data)
            print("{", end='')
            for k in v:
                if k == 'flat':
                    continue
                if opt_hex:
                    print("'%s': 0x%x" % (k, v[k]), end=', ')
                else:
                    print("'%s': %d" % (k, v[k]), end=', ')
            if opt_hex:
                print("'flat': 0x%x" % (v['flat']), end='')
            else:
                print("'flat': %d" % (v['flat']), end='')
            print("}")
            gdb.add_history(v['flat'])
        elif reg_field != None:
            v = self.encode_apb_value(reg, reg_data)
            if opt_hex:
                print("0x%x" % v[reg_field['name']])
            else:
                print("%u" % v[reg_field['name']])
            gdb.add_history(v[reg_field['name']])
        else:
            if opt_hex:
                print("0x%08x" % reg_data)
            else:
                print("%u" % reg_data)
            gdb.add_history(reg_data)

    def cmd_write(self, argv, from_tty):
        # parse options first and remove them from argv
        options = []
        # We iterate over a copy of argv since we are modifying it on the fly
        for arg in list(argv):
            if arg.startswith('/'):
                options.append(arg[1:])
                argv.remove(arg)
        # Write takes in the register name and value separated by '='
        if len(argv) < 2:
            raise gdb.GdbError("Invalid syntax for subcommand '%s' (expected a register)." % argv[0])
        write_argv = ''.join(argv[1:]).split('=')
        if len(write_argv) != 2:
            raise gdb.GdbError("Invalid syntax for subcommand '%s' (expected a register and value separated by '=', got '%s')." % (argv[0], ' '.join(argv[1:])))
        reg_name = write_argv[0]
        # Check for options
        opt_hex = False
        opt_abs = False
        opt_32 = False
        opt_quiet = False
        for opt in options:
            if opt == 'x':
                opt_hex = True
            elif opt == 'a':
                opt_abs = True
            elif opt == '32':
                opt_32 = True
            elif opt == 'q':
                opt_quiet = True
            else:
                raise gdb.GdbError("Unknown option '/%s' to 'apb write' command. Try 'help apb'." % opt)
        # Check if the argument is a string or a number
        try:
            reg_addr = int(reg_name, 0)
            reg_byname = False
        except:
            # Not a number
            reg_addr = 0
            reg_byname = True
            pass
        reg_field = None
        if reg_byname:
            if self.regspec == None:
                raise gdb.GdbError("To refer to a register by name you must have loaded a database with 'apb load'. Try 'help apb'.")
            if opt_abs:
                raise gdb.GdbError("The /a option is not supported for the <reg_name> variant of the 'apb write' command. Try 'help apb'.")
            reg_name_list = reg_name.split('.')
            if len(reg_name_list) > 2:
                reg_name = '.'.join(reg_name_list[0:2])
                # Note that there should not be any dot in the field name, this
                # is here to make sure if an invalid name is given a piece of it
                # won't be ignored.
                reg_field_name = '.'.join(reg_name_list[2:])
            else:
                reg_name = '.'.join(reg_name_list)
                reg_field_name = None
            reg = self.lookup_reg_by_name(reg_name)
            if reg == None:
                raise gdb.GdbError("No register named %s found, try 'apb info %s'." % (reg_name, reg_name))
            if (reg_field_name != None) and (reg_field_name != 'flat'):
                for field in reg['fields']:
                    if field['name'] == reg_field_name:
                        reg_field = field
                if reg_field == None:
                    raise gdb.GdbError("No field named %s in register %s." % (reg_field_name, reg_name))
            reg_addr = reg['address']
        elif self.regspec != None:
            reg = self.lookup_reg_by_addr(reg_addr)
        else:
            # If no db is loaded we still support accessing APB we just will
            # not be able to decode the register.
            reg = None
        if opt_32:
            reg_size = 32
        elif reg != None:
            reg_size = reg['width']
        else:
            # Assume register is 32b
            reg_size = 32
        # Parse the value which could be a number or a dictionary
        try:
            reg_value_obj = eval(write_argv[1])
        except:
            raise gdb.GdbError("'%s' is not a recognized value." % (write_argv[1]))
        if isinstance(reg_value_obj, int):
            reg_value = reg_value_obj
            # If we are only changing a field we must read the register first
            if reg_field != None:
                reg_data = self.read_apb(reg_addr, reg_size, opt_abs)
                field_shift = reg_field['bit_lo']
                field_mask = ((1<<reg_field['bit_width']) - 1) << field_shift
                reg_value = ((reg_data & field_mask) ^ reg_data) | ((reg_value<<field_shift) & field_mask)
        elif isinstance(reg_value_obj, dict):
            if reg == None:
                raise gdb.GdbError("Passing a value as a dictionary is not supported for register %s." % write_argv[0])
            elif reg_field != None:
                raise gdb.GdbError("Passing a value as a dictionary is not supported for a register field.")
            reg_value = self.decode_apb_value(reg, reg_value_obj)
        else:
            raise gdb.GdbError("%s is not a valid number or dictionary to write to register %s." % (write_argv[1], write_argv[0]))
        self.write_apb(reg_addr, reg_size, reg_value, opt_abs)
        if reg != None:
            v = self.encode_apb_value(reg, reg_value)
            if not opt_quiet:
                print("{", end='')
                for k in v:
                    if k == 'flat':
                        continue
                    if opt_hex:
                        print("'%s': 0x%x" % (k, v[k]), end=', ')
                    else:
                        print("'%s': %d" % (k, v[k]), end=', ')
                if opt_hex:
                    print("'flat': 0x%x" % (v['flat']), end='')
                else:
                    print("'flat': %d" % (v['flat']), end='')
                print("}")
            gdb.add_history(v['flat'])
        else:
            if not opt_quiet:
                if opt_hex:
                    print("0x%08x" % reg_value)
                else:
                    print("%u" % reg_value)
            gdb.add_history(reg_value)

    def cmd_info(self, argv, from_tty):
        # parse options first and remove them from argv
        options = []
        # We iterate over a copy of argv since we are modifying it on the fly
        for arg in list(argv):
            if arg.startswith('/'):
                options.append(arg[1:])
                argv.remove(arg)
        if len(argv) != 2:
            raise gdb.GdbError("Invalid syntax for subcommand '%s' (expected a single string or number, got '%s')." % (argv[0], ' '.join(argv[1:])))
        # This command needs a database loaded to be of any use
        if self.regspec == None:
            raise gdb.GdbError("To use the 'apb info' command you must have loaded a database with 'apb load'. Try 'help apb'.")
        short_info = False
        for opt in options:
            if opt == 's':
                short_info = True
            else:
                raise gdb.GdbError("Unsupported option /%s for command '%s'." % (argv[0], opt))
        # Check if the argument is a string (in which case we will
        # search for registers by name) or a number, in which case we will
        # attempt to find a register matching that address (offset by base)
        try:
            info_reg_addr = int(argv[1], 0)
            info_reg_byname = False
        except:
            # Not a number
            info_reg_addr = 0
            info_reg_byname = True
            pass
        if info_reg_byname:
            # Look for any register whose name match argv[1] treating argv[1] as a regular expression
            matches = []
            pat = argv[1]
            for component_name, component in self.regspec.items():
                if 'registers' in component:
                    for reg in component['registers'].values():
                        regfn = "%s.%s" % (component_name,reg['name'])
                        if re.search(pat, regfn) != None:
                            # Each match is a tuple name, reg
                            matches.append((regfn, reg))
            if len(matches) == 0:
                raise gdb.GdbError("No register found matching pattern '%s'." % (pat))
            # If the user called the register by exact name we treat this
            # command a bit differently. We assume the user is not looking
            # for the name itself.
            if (len(matches) == 1) and (matches[0][0] == pat):
                addr = matches[0][1]['address']+self.base
                if short_info:
                    print("0x%08x" % addr)
                else:
                    self.print_register(matches[0][1])
                gdb.add_history(addr)
            else:
                if short_info:
                    for match in matches:
                        print(match[0])
                else:
                    print("Found %d matches for '%s':" % (len(matches), pat))
                    # We justify based on longest name
                    max_str = 0
                    for match in matches:
                        max_str = max(max_str, len(match[0]))
                    for match in matches:
                        header = match[0]
                        header += ' ' * (max_str-len(header))
                        header += ': '
                        self.print_register(match[1], header)
                        print()
                # Add register names to history as a space separated list
                reg_names = [match[0] for match in matches]
                gdb.add_history(' '.join(reg_names))
        else:
            # Look for any register whose address match
            reg = self.lookup_reg_by_addr(info_reg_addr)
            if reg == None:
                raise gdb.GdbError("No register found at address 0x%x." % (info_reg_addr))
            else:
                if short_info:
                    print(reg['name'])
                else:
                    print("Register at address 0x%08x is %s:" % (info_reg_addr, reg['name']))
                    self.print_register(reg)
                gdb.add_history(reg['name'])

    def cmd_load(self, argv, from_tty):
        if len(argv) != 2:
            raise gdb.GdbError("Invalid syntax for subcommand '%s' (expected a string got '%s')." % (argv[0], ' '.join(argv[1:])))
        print("Loading APB registers database from %s..." % argv[1])
        # Clear our config
        self.regspec = None
        self.loaded_regspec = None
        self.smt_thread = -1
        self.smt_nthreads = -1
        try:
            self.loaded_regspec = ext_spr_spec_db.load_yaml(argv[1], 'dbg')
        except Exception as e:
            raise gdb.GdbError("Unable to load database in '%s': %s." % (argv[1], e))
        # Find the number of threads in this core, if none found it will be 0
        nth = -1
        for cmp in self.loaded_regspec.values():
            if cmp['smt']:
                if cmp['thread'] > nth:
                    nth = cmp['thread']
        self.smt_nthreads = nth+1
        # self.regspec is the active representation, when SMT is off it is loaded_regspec
        self.regspec = self.loaded_regspec
        nregs = 0
        for component in self.loaded_regspec.values():
            if 'registers' in component:
                nregs += len(component['registers'])
        print("Loading APB registers database from %s: done, found %d APB registers." % (argv[1], nregs))

    def cmd_set(self, argv, from_tty):
        if len(argv) < 2:
            raise gdb.GdbError("Invalid syntax, %s command requires a parameter. Try 'help apb'." % argv[0])
        if argv[1] == 'base':
            if len(argv) == 2:
                print("Currently using 0x%08x as the base address for APB registers." % self.base)
                return
            elif len(argv) > 3:
                raise gdb.GdbError("Invalid syntax for %s %s command. Try 'help apb'." % (argv[0], argv[1]))
            try:
                self.base = int(argv[2], 0)
            except:
                raise gdb.GdbError("Invalid base address '%s', it must be a number." % argv[2])
            print("Using 0x%08x as the base address for APB registers." % self.base)
        elif argv[1] == 'access':
            if len(argv) == 2:
                # Return the current config
                if self.access_mode == 'core':
                    print("Currently using core memory accesses at offset 0x%x to access APB." % self.access_arg)
                elif self.access_mode == 'openocd':
                    print("Currently using the monitor command targeting bus %s + 0x%x to access APB." % self.access_arg)
                else:
                    raise gdb.GdbError("INTERNAL ERROR: unknown access mode %s." % self.access_mode)
                return
            elif argv[2] == 'core':
                if len(argv) < 4:
                    raise gdb.GdbError("Base address is missing. Try 'help apb'.")
                self.access_mode = argv[2]
                # We concatenate the rest of the args to make sure they are handled rather than ignored
                addr_str = ' '.join(argv[3:])
                try:
                    self.access_arg = int(addr_str, 0)
                except:
                    raise gdb.GdbError("Invalid base address '%s', it must be a number." % addr_str)
                print("Now using core memory accesses at offset 0x%x to access APB bus." % (self.access_arg))
            elif argv[2] == 'openocd':
                openocd.check_attached()
                if len(argv) == 3:
                    # Check the list of targets for ones named .apb, if only one is found
                    # pick it, otherwise display the list and bailout.
                    targets_list = openocd.get_targets()
                    valid_targets = []
                    for t in targets_list:
                        if re.search(".apb$", t) != None:
                            valid_targets.append(t)
                    if len(valid_targets) == 1:
                        self.access_mode = argv[2]
                        self.access_arg = valid_targets[0]
                    else:
                        print("The following APB buses are available to choose from:")
                        for t in valid_targets:
                            print(t)
                        raise gdb.GdbError("You must pick which APB bus to use as argument.")
                elif len(argv) > 5:
                    raise gdb.GdbError("Invalid syntax for %s %s command. Try 'help apb'." % (argv[0], argv[1]))
                else:
                    self.access_mode = argv[2]
                    if len(argv) == 4:
                        offset = 0
                    else:
                        try:
                            offset = int(argv[4], 0)
                        except:
                            raise gdb.GdbError("Invalid syntax for %s %s command, the target %s or offset %s are invalid. Try 'help apb'." % (argv[0], argv[1], argv[3], argv[4]))
                    self.access_arg = (argv[3], offset)
                print("Now using OpenOCD to access APB bus through target %s offset 0x%x." % self.access_arg)
            else:
                raise gdb.GdbError("Invalid access type '%s'. Try 'help apb'." % argv[2])
        elif argv[1] == 'smt':
            if len(argv) == 2:
                if self.smt_nthreads == 0:
                    print("SMT mode is not supported on this core.")
                elif self.smt_thread < 0:
                    print("SMT mode is currently off.")
                else:
                    print("SMT mode is currently enabled and selected thread is %d." % self.smt_thread)
            elif len(argv) > 3:
                raise gdb.GdbError("Invalid arguments '%s' to set smt." % ' '.join(argv[2:]))
            elif argv[2] == 'off':
                self.smt_thread = -1
                self.regspec = self.loaded_regspec
            elif self.smt_nthreads == 0:
                raise gdb.GdbError("No SMT support in this core, only 'set smt off' is supported.")
            else:
                try:
                    th = int(argv[2], 0)
                except:
                    raise gdb.GdbError("Invalid argument '%s' to set smt." % argv[2])
                if (self.smt_nthreads >= 0) and (th >= self.smt_nthreads):
                    raise gdb.GdbError("Thread %d does not exist (max is %d)." % (th, self.smt_nthreads-1))
                self.smt_thread = th
                # Create a new regspec that contains only thread <th> components
                # and components that are not smt
                self.regspec = {}
                for cmp in self.loaded_regspec.values():
                    if (not cmp['smt']) or (cmp['thread'] == self.smt_thread):
                        self.regspec[cmp['name']] = cmp
        elif argv[1] == 'debug':
            if len(argv) == 2:
                print("APB debug mode is currently %s." % ('enabled' if self.debug else 'disabled'))
            elif len(argv) > 3:
                raise gdb.GdbError("Invalid argument '%s' to %s." % (' '.join(argv[2:]), ' '.join(argv[0:1])))
            elif argv[2] == 'on':
                self.debug = True
                print("APB debug mode is now enabled.")
            elif argv[2] == 'off':
                self.debug = False
                print("APB debug mode is now disabled.")
            else:
                raise gdb.GdbError("Invalid argument '%s' to %s." % (argv[2], ' '.join(argv[0:1])))
        else:
            raise gdb.GdbError("Unknown %s subcommand %s. Try 'help apb'." % (argv[0], argv[1]))

    def invoke(self, args, from_tty):
        argv = gdb.string_to_argv(args)
        if len(argv) == 0:
            raise gdb.GdbError("The apb command needs arguments, try 'help apb'.")
        elif not argv[0] in self.supported_commands:
            raise gdb.GdbError("Invalid subcommand %s, try 'help apb'." % argv[0])
        elif argv[0] == 'read':
            self.cmd_read(argv, from_tty)
        elif argv[0] == 'write':
            self.cmd_write(argv, from_tty)
        elif argv[0] == 'info':
            self.cmd_info(argv, from_tty)
        elif argv[0] == 'load':
            self.dont_repeat()
            self.cmd_load(argv, from_tty)
        elif argv[0] == 'set':
            self.cmd_set(argv, from_tty)
        else:
            raise gdb.GdbError("INTERNAL ERROR: unhandled command '%s'" % argv[0])

    #########################################################
    # External python APIs. The following functions can be
    # accessed from other python code with:
    # from apb import apb_reg_access
    # apb_reg_access.<api>()
    #########################################################
    def lookup_reg_by_name(self, name):
        """External Python API: use with apb.apb_reg_access object.
        Return the register entry that match <name>. This API assumes only one match is possible.
        """
        if name == None:
            raise gdb.GdbError("lookup_reg_by_name(): Missing name.")
        elif self.regspec == None:
            raise gdb.GdbError("lookup_reg_by_name(): No database loaded, use apb load first.")
        lname = name.split('.')
        if len(lname) != 2:
            raise gdb.GdbError("Invalid register name '%s', expected <component>.<register>." % name)
        if lname[0] not in self.regspec:
            return None
        if 'registers' not in self.regspec[lname[0]]:
            return None
        if lname[1] not in self.regspec[lname[0]]['registers']:
            return None
        return self.regspec[lname[0]]['registers'][lname[1]]

    def read(self, reg):
        """External Python API: use with apb.apb_reg_access object.
        Read an APB register taking the register as a dictionary as returned by lookup_reg_by_name
        and return the value as a dictionary of fields plus a 'flat' entry containing the whole register value."""
        if reg == None:
            raise gdb.GdbError("read(): Missing register dictionary.")
        # Support passing a string as the register name
        if isinstance(reg, str):
            reg = self.lookup_reg_by_name(reg)
        if 'address' not in reg:
            raise gdb.GdbError("read(): Missing address in register dictionary.")
        if 'width' not in reg:
            raise gdb.GdbError("read(): Missing width in register dictionary.")
        return self.encode_apb_value(reg, self.read_apb(reg['address'], reg['width']))

    def read_absolute(self, addr, size):
        """External Python API: use with apb.apb_reg_access object.
        Read an APB register treationg addr as an absolute address (ie not appending the base address)."""
        if not isinstance(addr, int):
            raise gdb.GdbError("read_absolute(): Invalid address argument.")
        if not isinstance(size, int):
            raise gdb.GdbError("read_absolute(): Invalid size argument.")
        return self.read_apb(addr, size, absolute_addr=True)

    def write(self, reg, value):
        """External Python API: use with apb.apb_reg_access object.
        Write an APB register taking the register as a dictionary as returned by lookup_reg_by_name
        and a value as a dictionary of fields as returned by encode_apb_value. If a field is not
        specified reset value will be used, if flat is specified it will be assigned first then
        other fileds will be used to overwrite flat."""
        if reg == None:
            raise gdb.GdbError("write(): Missing register dictionary.")
        # Support passing a string as the register name
        if isinstance(reg, str):
            reg = self.lookup_reg_by_name(reg)
        if 'address' not in reg:
            raise gdb.GdbError("write(): Missing address in register dictionary.")
        if 'width' not in reg:
            raise gdb.GdbError("write(): Missing width in register dictionary.")
        if value == None:
            raise gdb.GdbError("write(): Missing value dictionary.")
        # Support passing an integer
        if isinstance(value, int):
            intv = value
        elif isinstance(value, str):
            try:
                intv = int(value, 0)
            except:
                raise gdb.GdbError("write(): Invalid integer value '%s'." % value)
        else:
            intv = self.decode_apb_value(reg, value)
        return self.write_apb(reg['address'], reg['width'], intv)

    def write_absolute(self, addr, size, value):
        """External Python API: use with apb.apb_reg_access object.
        Write an APB register treationg addr as an absolute address (ie not appending the base address)."""
        if not isinstance(addr, int):
            raise gdb.GdbError("write_absolute(): Invalid address argument.")
        if not isinstance(size, int):
            raise gdb.GdbError("write_absolute(): Invalid size argument.")
        if not isinstance(value, int):
            raise gdb.GdbError("write_absolute(): Invalid value argument.")
        return self.write_apb(addr, size, value, absolute_addr=True)

    def encode_apb_value(self, reg, value = None):
        """External Python API: use with apb.apb_reg_access object.
        Create a dictionary that represent <reg> fields and fill it with <value>.
        Also add an extra entry called 'flat' which contains the whole register value.
        """
        if reg == None:
            raise gdb.GdbError("encode_apb_value(): Missing register dictionary.")
        if 'fields' not in reg:
            raise gdb.GdbError("encode_apb_value(): Missing fields in register dictionary.")
        if (value != None) and not isinstance(value, int):
            raise gdb.GdbError("encode_apb_value(): value when specified must be an integer.")
        regv = {}
        if value != None:
            regv['flat'] = value
        else:
            regv['flat'] = 0
        for field in reg['fields']:
            field_shifted_mask = (1<<int(field['bit_width']))-1
            field_shift = field['bit_lo']
            if value != None:
                fieldv = (value >> field_shift) & field_shifted_mask
            elif 'reset_value' in field:
                fieldv = field['reset_value']
                regv['flat'] |= fieldv << field_shift   
            else:
                fieldv = 0
            regv[field['name']] = fieldv
        return regv

    def decode_apb_value(self, reg, value = None):
        """External Python API: use with apb.apb_reg_access object.
        Decode a dictionary of fields as returned by encode_apb_value into an integer. If value
        is None then it returns the reset value of the register. If value contains fields that
        are not in the register then they are ignored.
        """
        if reg == None:
            raise gdb.GdbError("decode_apb_value(): Missing register dictionary.")
        if 'fields' not in reg:
            raise gdb.GdbError("decode_apb_value(): Missing fields in register dictionary.")
        if (value != None) and ('flat' in value):
            intv = value['flat']
        else:
            intv = 0
        for field in reg['fields']:
            if not all(attr in field for attr in ['bit_width', 'name', 'bit_lo', 'reset_value']):
                raise gdb.GdbError("decode_apb_value(): Missing entries in field %s dictionary." % field['name'])
            field_shifted_mask = (1<<int(field['bit_width']))-1
            field_shift = field['bit_lo']
            if (value != None) and (field['name'] in value):
                fieldv = value[field['name']]
            else:
                fieldv = field['reset_value']
            intv |= (fieldv & field_shifted_mask) << field_shift
        return intv



