import gdb
import spr_spec_db
import re
import core
from apb import apb_reg_access
import time
import openocd

_SPR_COMMAND_DOC_PUBLIC = """
    This command can decode, read and write ARM Special Purpose Registers
    (SPRs) using various methods controlled through spr set. It supports the
    following subcommands:
        set <parameter> [ <args> ]
            The following variants are supported:
            access gdb | openocd: select how to access SPR registers,
            either using the gdb register interface
            (only works when target is stopped) or OpenOCD's msr/mrs instruction
            injection (only work when core is in debug state).
            thread <n>: which thread to access if the core supports SMT (default
            is zero).
            debug: on | off: enable or disable extra debug messages.
            quick: on | off: favor speed over error checking, if an error occurs
            bad data may be returned or the interface may crash
        read [/x] [/n] <reg_name> | <reg_enc> | <reg_name>.<field_name>
            Read the specified register from the current core and return
            its content. This command can only be used if a running target
            is attached.
            For the <reg_name> variant by default a dictionary of
            the fields in the register will be returned. If /n is specified
            then the value will be returned instead.
            For the <reg_enc> variant the value of the register is returned
            and /n has no effect. The encoding is a list of numbers separated by
            commas as listed in ARM's ARM.
            For the <reg_name>.<field_name> variant the value of the field is
            returned and /n has no effect.
            For all variants if /x is specified the number are hex numbers
            instead of decimals.
        write [/q] [/x] [/c] <reg_name> | <reg_env> | <reg_name>.<field_name> = <value>
            Write <value> to the specified register, if a field is specified
            then a read-modify-write will be performed. <value> must be a
            number that fits in the register or field and this command can
            only be used if a running target is attached.
            Option /q will not print the value written, option /x will print it in
            hex rather than decimal.
            Option /c will make the write wait for a confirmation that the
            register new value was taken into account through a Context
            Synchronization Event (CSE).
        info [/s] <pattern> | <reg_name> | <reg_enc>
            Return the name, encoding and fields of all registers
            matching the specified pattern, name or encoding. If /s is specified
            then only the name (<pattern> or <reg_enc> variants) or encoding
            (<reg_name> variant) is returned.
        load <yml_db>
            Load the registers description from a YAML database specified by
            <yml_db>. This is necessary before using the info command or
            using the <reg_name>* variants of the other commands.
    """

class spr(gdb.Command):
    __doc__ = _SPR_COMMAND_DOC_PUBLIC
    supported_commands = ['read', 'write', 'info', 'load', 'set']
    regspec_loader = None
    access_mode = 'openocd'
    supported_access_modes = ['gdb', 'openocd']
    smt_thread = 0
    smt_nthreads = 2
    debug = False
    quick = True

    def __init__(self):
        super(spr, self).__init__("spr", gdb.COMMAND_DATA)

    def print_register(self, reg, header = ''):
        print(f"{header}Name: {reg['name']}")
        print(f"{header}Description: {reg['title']}")
        if reg['cse']:
            print(f"{header}This register requires a Context Synchronization Event after it was written.")
        else:
            print(f"{header}Updates to this register are immediate.")
        if reg['smt_flag']:
            print(f"{header}This register is independent for each thread.")
        else:
            print(f"{header}This register is common to all threads in the core.")
        print(f"{header}Encoding: {reg['isa_addr']}")
        print(f"{header}Group: {reg['group']}")
        print(f"{header}Alias: {reg['alias']}")
        if 'fields' in reg:
            print(f"{header}Fields ({len(reg['fields'])}):")
            for field in reg['fields']:
                print("%s\t[%d:%d]: %s (reset=%s, access=%s)." % (header, field['bit_hi'], field['bit_lo'], field['name'], field['reset_value'], field['access']))

    def encode_isa_addr(self, addr):
        return "%d_%d_%02d_%02d_%d" % (addr['op0'], addr['op1'], addr['CRn'], addr['CRm'], addr['op2'])

    def decode_isa_addr(self, string):
        """Check if the string is a valid ISA address and return a dictionary with op0, op1, CRn, CRm, op2."""
        split_str = string.split('_')
        if len(split_str) == 5:
            if (split_str[0][0] == 's') or (split_str[0][0] == 'S'):
                split_str[0] = split_str[0][1:]
            if (split_str[2][0] == 'c') or (split_str[2][0] == 'C'):
                split_str[2] = split_str[2][1:]
            if (split_str[3][0] == 'c') or (split_str[3][0] == 'C'):
                split_str[3] = split_str[3][1:]
            try:
                return {
                    'op0': int(split_str[0]),
                    'op1': int(split_str[1]),
                    'CRn': int(split_str[2]),
                    'CRm': int(split_str[3]),
                    'op2': int(split_str[4])
                }
            except:
                return None
        else:
            return None

    def read_with_gdb(self, spr_reg_name, spr_reg_enc):
        """Read the value of the specified SPR register using GDB state APIs."""
        resp = gdb.execute("info registers %s" % spr_reg_name, False, True)
        m = re.match(r'%s\s+0x([0-9a-zA-Z]+)\s.*' % spr_reg_name, resp)
        if m == None:
            raise gdb.GdbError("Could not retrieve value of register '%s' through info reg: %s." % (spr_reg_name, resp))
        return int(m.group(1), 16)

    def read_with_openocd(self, spr_reg_name, spr_reg_enc):
        """Read the value of the specified SPR register using OpenOCD Debug State code injection."""
        ccore = core.core_control.get_active_core()
        if ccore['state'] != 'halted':
            raise gdb.GdbError("Active core %s is not in Debug State." % ccore['name'])
        try:
            result = openocd.execute("%s aarch64 mrs %d %d %d %d %d" % (ccore['target'], spr_reg_enc['op0'], spr_reg_enc['op1'],spr_reg_enc['CRn'], spr_reg_enc['CRm'], spr_reg_enc['op2']));
        except:
            raise gdb.GdbError("Failed to read SPR %s." % (spr_reg_name))
        try:
            v = int(result, 0)
        except:
            raise gdb.GdbError("OpenOCD returned unexpected message '%s' when reading SPR %s." % (result, spr_reg_name))
        return v

    def read_spr(self, reg):
        """Read the value of the specified SPR register. The argument reg must
        be a dictionary containing the following fields: isa_addr and name.
        """
        if not all(attr in reg for attr in ['isa_addr', 'name']):
            raise gdb.GdbError("read_spr(): Invalid register, check all required elements are provided.")
        spr_reg_enc = self.decode_isa_addr(reg['isa_addr'])
        if spr_reg_enc == None:
            raise gdb.GdbError("read_spr(): Invalid encoding '%s' for register %s." % (reg['isa_addr'], reg['name']))
        elif self.access_mode == 'gdb':
            v = self.read_with_gdb(reg['name'], spr_reg_enc)
        elif self.access_mode == 'openocd':
            v = self.read_with_openocd(reg['name'], spr_reg_enc)
        else:
            raise gdb.GdbError("INTERNAL ERROR: unknown access mode %s." % self.access_mode)
        if self.debug:
            print("SPR: %s => 0x%016x (%s)." % (reg['name'], v, self.access_mode))
        return v

    def write_with_gdb(self, spr_reg_name, spr_reg_enc, value):
        """Write the value to the specified SPR register using GDB registers state APIs."""
        resp = gdb.execute("set $%s = 0x%x" % (spr_reg_name, value), False, True)

    def write_with_openocd(self, spr_reg_name, spr_reg_enc, value):
        """Write the value to the specified SPR register using OpenOCD Debug State code injection."""
        ccore = core.core_control.get_active_core()
        if ccore['state'] != 'halted':
            raise gdb.GdbError("Active core %s is not in Debug State." % ccore['name'])
        try:
            result = openocd.execute("%s aarch64 msr %d %d %d %d %d 0x%016x" % (ccore['target'], spr_reg_enc['op0'], spr_reg_enc['op1'],spr_reg_enc['CRn'], spr_reg_enc['CRm'], spr_reg_enc['op2'], value));
        except:
            raise gdb.GdbError("Failed to write SPR %s." % (spr_reg_name))
        if result != '':
            raise gdb.GdbError("OpenOCD returned unexpected message '%s' when writing SPR %s." % (result, spr_reg_name))

    def write_spr(self, reg, value, wait_cse = False):
        """Write the value to the specified SPR register. The argument reg must
        be a dictionary containing the following fields: isa_addr and name.
        """
        if not all(attr in reg for attr in ['isa_addr', 'name']):
            raise gdb.GdbError("write_spr(): Invalid register, check all required elements are provided.")
        spr_reg_enc = self.decode_isa_addr(reg['isa_addr'])
        if spr_reg_enc == None:
            raise gdb.GdbError("write_spr(): Invalid encoding '%s' for register %s." % (reg['isa_addr'], reg['name']))
        elif value == None:
            raise gdb.GdbError("write_spr(): Missing value argument.")
        elif self.access_mode == 'gdb':
            self.write_with_gdb(reg['name'], spr_reg_enc, value)
        elif self.access_mode == 'openocd':
            self.write_with_openocd(reg['name'], spr_reg_enc, value)
        else:
            raise gdb.GdbError("INTERNAL ERROR: unknown access mode %s." % self.access_mode)
        if self.debug:
            print("SPR: %s <= 0x%016x (%s)." % (reg['name'], value, self.access_mode))

    def complete_helper_commands(self, textv, word, commands):
        """Helper function for code that would otherwise be duplicated"""
        if len(textv) == 0:
            return commands
        elif (len(textv) == 1) and (textv[0] == word):
                return [s for s in commands if s.startswith(word)]
        else:
            return None

    def complete(self, text, word):
        textv = gdb.string_to_argv(text)
        # First we ignore all optional arguments
        for arg in list(textv):
            if arg.startswith('/'):
                textv.remove(arg)
        # If completion is on command type return the intersect of word
        # and the supported commands.
        opts = self.complete_helper_commands(textv, word, self.supported_commands)
        if opts != None:
            return opts
        elif textv[0] == 'load':
            # load is looking for a file, use GDB's handler for that
            if len(textv) <= 2:
                return gdb.COMPLETE_FILENAME
            else:
                return gdb.COMPLETE_NONE
        elif textv[0] == 'set':
            # Set only support a subset of subcommands
            opts = self.complete_helper_commands(textv[1:], word, ['access', 'thread', 'debug', 'quick'])
            if opts != None:
                return opts
            elif textv[1] == 'access':
                opts = self.complete_helper_commands(textv[2:], word, self.supported_access_modes)
                if opts != None:
                    return opts
                else:
                    return gdb.COMPLETE_NONE
            elif textv[1] == 'thread':
                thread_list = []
                # Add all threads to the list of valid options
                for n in range(self.smt_nthreads):
                    thread_list.append("%d" % n)
                opts = self.complete_helper_commands(textv[2:], word, thread_list)
                if opts != None:
                    return opts
                else:
                    return gdb.COMPLETE_NONE
            elif (textv[1] == 'debug') or (textv[1] == 'quick'):
                opts = self.complete_helper_commands(textv[2:], word, ['on', 'off'])
                if opts != None:
                    return opts
                else:
                    return gdb.COMPLETE_NONE
            else:
                # No completion for this subcommand's arguments
                return gdb.COMPLETE_NONE
        elif not textv[0] in self.supported_commands:
            # the command mentioned is not supported
            return gdb.COMPLETE_NONE
        # If we get here we are looking for a register or register+field.
        # Now the register should be in position 2, check this is what the
        # user is trying to complete, otherwise return as we cannot complete
        # other parameters.
        if len(textv) > 2:
            return gdb.COMPLETE_NONE
        # Now we can search but we need a database
        if self.regspec_loader == None:
            return gdb.COMPLETE_NONE
        if len(textv) < 2:
            # User has not yet typed any start of a name
            return list(self.regspec_loader.registers.keys())
        # Now we know textv[1] exists
        regname = textv[1].split('.')
        nextname = (word == '') and not textv[1].endswith('.')
        if (len(regname) == 1) and not nextname:
            # Search for registers
            matches = [k for k in self.regspec_loader.registers.keys() if k.startswith(regname[0])]
            if len(matches) == 1:
                matches.append(matches[0] + '.')
            return matches
        elif not regname[0] in self.regspec_loader.registers:
            # Component name is bogus
            return gdb.COMPLETE_NONE
        elif (textv[0] != 'info') and (len(regname) == 2) and (not nextname):
            # Search for fields within the register, not for info command
            # which only works for registers.
            flist = [k['name'] for k in self.regspec_loader.registers[regname[0]]['fields']]
            flist.append('flat')
            return [l for l in flist if l.startswith(regname[1])]
        else:
            # Bogus name, we do not support more than reg.field
            return gdb.COMPLETE_NONE

    def cmd_read(self, argv, from_tty):
        # parse options first and remove them from argv
        options = []
        # We iterate over a copy of argv since we are modifying it on the fly
        for arg in list(argv):
            if arg.startswith('/'):
                options.append(arg[1:])
                argv.remove(arg)
        if len(argv) != 2:
            raise gdb.GdbError("Invalid syntax for subcommand '%s' (expected a single string or number, got '%s')." % (argv[0], ' '.join(argv[1:])))
        opt_hex = False
        opt_num = False
        for opt in options:
            if opt == 'x':
                opt_hex = True
            elif opt == 'n':
                opt_num = True
            else:
                raise gdb.GdbError("Unknown option '/%s' to 'spr read' command. Try 'help spr'." % opt)
        # Check if the argument is an encoding or a name
        isa_addr = self.decode_isa_addr(argv[1])
        reg_field_name = None
        if self.regspec_loader == None:
            if isa_addr == None:
                raise gdb.GdbError("Register %s cannot be decoded since no database is loaded." % argv[1])
            reg = {
                'isa_addr': self.encode_isa_addr(isa_addr),
                'name': argv[1],
                'fields': [],
            }
        elif isa_addr != None:
            reg = self.regspec_loader.get_register_by_addr(self.encode_isa_addr(isa_addr))
        else:
            # Check if a field is appended at the end
            reg_name_list = argv[1].split('.')
            reg_name = reg_name_list[0]
            if len(reg_name_list) > 1:
                # Note that there should not be any dot in the field name, this
                # is here to make sure if an invalid name is given a piece of it
                # won't be ignored.
                reg_field_name = '.'.join(reg_name_list[1:])
            reg = self.lookup_reg_by_name(reg_name)
        if reg == None:
            raise gdb.GdbError("No register found matching encoding or name '%s'." % argv[1])
        elif reg_field_name != None:
            if reg_field_name == 'flat':
                reg_field_name = None
            else:
                reg_field_found = False
                for field in reg['fields']:
                    if field['name'] == reg_field_name:
                        reg_field_found = True
                        break
                if not reg_field_found:
                    raise gdb.GdbError("No field named %s in register %s." % (reg_field_name, reg['name']))
        reg_data = self.read_spr(reg)
        if reg_field_name != None:
            v = self.encode_spr_value(reg, reg_data)
            if reg_field_name not in v:
                raise gdb.GdbError("INTERNAL ERROR: No field named %s found in value of register %s." % (reg_field_name, reg['name']))
            elif opt_hex:
                print("0x%x" % v[reg_field_name])
            else:
                print("%d" % v[reg_field_name])
            gdb.add_history(v[reg_field_name])
        elif opt_num:
            if opt_hex:
                print("0x%08x" % reg_data)
            else:
                print("%u" % reg_data)
            gdb.add_history(reg_data)
        else:
            v = self.encode_spr_value(reg, reg_data)
            print("{", end='')
            for k in v:
                if k == 'flat':
                    continue
                if opt_hex:
                    print("'%s': 0x%x" % (k, v[k]), end=', ')
                else:
                    print("'%s': %d" % (k, v[k]), end=', ')
            if opt_hex:
                print("'flat': 0x%016x" % (v['flat']), end='')
            else:
                print("'flat': %d" % (v['flat']), end='')
            print("}")
            gdb.add_history(v['flat'])

    def cmd_write(self, argv, from_tty):
        # parse options first and remove them from argv
        options = []
        # We iterate over a copy of argv since we are modifying it on the fly
        for arg in list(argv):
            if arg.startswith('/'):
                options.append(arg[1:])
                argv.remove(arg)
        # Write takes in the register name and value separated by '='
        if len(argv) < 2:
            raise gdb.GdbError("Invalid syntax for subcommand '%s' (expected a register)." % argv[0])
        # Check for options
        opt_hex = False
        opt_cse = False
        opt_quiet = False
        for opt in options:
            if opt == 'x':
                opt_hex = True
            elif opt == 'c':
                opt_cse = True
            elif opt == 'q':
                opt_quiet = True
            else:
                raise gdb.GdbError("Unknown option '/%s' to 'apb write' command. Try 'help apb'." % opt)
        write_argv = ''.join(argv[1:]).split('=')
        if len(write_argv) != 2:
            raise gdb.GdbError("Invalid syntax for subcommand '%s' (expected a register and value separated by '=', got '%s')." % (argv[0], ' '.join(argv[1:])))
        # Check if the argument is an encoding or a name
        isa_addr = self.decode_isa_addr(write_argv[0])
        reg_field_name = None
        if self.regspec_loader == None:
            if isa_addr == None:
                raise gdb.GdbError("Register %s cannot be decoded since no database is loaded." % argv[1])
            reg = {
                'isa_addr': self.encode_isa_addr(isa_addr),
                'name': write_argv[0],
                'fields': []
            }
        elif isa_addr != None:
            reg = self.regspec_loader.get_register_by_addr(self.encode_isa_addr(isa_addr))
        else:
            # Check if a field is appended at the end
            reg_name_list = write_argv[0].split('.')
            reg_name = reg_name_list[0]
            if len(reg_name_list) > 1:
                # Note that there should not be any dot in the field name, this
                # is here to make sure if an invalid name is given a piece of it
                # won't be ignored.
                reg_field_name = '.'.join(reg_name_list[1:])
            reg = self.lookup_reg_by_name(reg_name)
        if reg == None:
            raise gdb.GdbError("No register found matching encoding or name '%s'." % argv[1])
        if (reg_field_name != None) and (reg_field_name != 'flat'):
            for field in reg['fields']:
                if field['name'] == reg_field_name:
                    reg_field = field
                    break
            if reg_field == None:
                raise gdb.GdbError("No field named %s found in register %s." % (reg_field_name, reg['name']))
        else:
            reg_field = None
        # Parse the value which could be a number or a dictionary
        try:
            reg_value_obj = eval(write_argv[1])
        except:
            raise gdb.GdbError("'%s' is not a recognized value." % (write_argv[1]))
        if isinstance(reg_value_obj, int):
            reg_value = reg_value_obj
            if reg_field != None:
                value = self.read_spr(reg)
                reg_value = (value & ~((1<<(reg_field['bit_hi']-reg_field['bit_lo']+1))-1)) | (reg_value << reg_field['bit_lo'])
        elif isinstance(reg_value_obj, dict):
            if reg_field != None:
                raise gdb.GdbError("Passing a value as a dictionary is not supported for a register field.")
            reg_value = self.decode_spr_value(reg, reg_value_obj)
        else:
            raise gdb.GdbError("%s is not a valid number or dictionary to write to register %s." % (write_argv[1], write_argv[0]))
        self.write_spr(reg, reg_value, opt_cse)
        v = self.encode_spr_value(reg, reg_value)
        if not opt_quiet:
            print("{", end='')
            for k in v:
                if k == 'flat':
                    continue
                if opt_hex:
                    print("'%s': 0x%x" % (k, v[k]), end=', ')
                else:
                    print("'%s': %d" % (k, v[k]), end=', ')
            if opt_hex:
                print("'flat': 0x%016x" % (v['flat']), end='')
            else:
                print("'flat': %d" % (v['flat']), end='')
            print("}")
        gdb.add_history(v['flat'])

    def cmd_info(self, argv, from_tty):
        # This command needs a database loaded to be of any use
        if self.regspec_loader == None:
            raise gdb.GdbError("To use the 'spr info' command you must have loaded a database with 'spr load'. Try 'help spr'.")
        # parse options first and remove them from argv
        options = []
        # We iterate over a copy of argv since we are modifying it on the fly
        for arg in list(argv):
            if arg.startswith('/'):
                options.append(arg[1:])
                argv.remove(arg)
        if len(argv) != 2:
            raise gdb.GdbError("Invalid syntax for subcommand '%s' (expected a single string or encoding, got '%s')." % (argv[0], ' '.join(argv[1:])))
        short_info = False
        for opt in options:
            if opt == 's':
                short_info = True
            else:
                raise gdb.GdbError("Unsupported option /%s for command '%s'." % (argv[0], opt))
        # Check if the argument is an ISA encoding
        isa_addr = self.decode_isa_addr(argv[1])
        if isa_addr != None:
            reg = self.regspec_loader.get_register_by_addr(self.encode_isa_addr(isa_addr))
            if reg == None:
                raise gdb.GdbError("No register found matching encoding '%s'." % self.encode_isa_addr(isa_addr))
            elif short_info:
                print("%s" % reg['name'])
            else:
                print("Register with encoding %s is %s:" % (argv[1], reg['name']))
                self.print_register(reg)
            gdb.add_history(reg['name'])
        else:
            matches = self.regspec_loader.get_registers_by_name_pattern(argv[1], True)
            if len(matches) == 0:
                raise gdb.GdbError("No register found matching name '%s'." % argv[1])
            elif len(matches) == 1:
                reg = matches[0][1]
                if short_info:
                    print("%s" % reg['isa_addr'])
                else:
                    self.print_register(reg)
                gdb.add_history(reg['isa_addr'])
            else:
                if short_info:
                    for match in matches:
                        print(match[1]['name'])
                else:
                    print("Found %d matches for '%s':" % (len(matches), argv[1]))
                    # We justify based on longest name
                    max_str = 0
                    for match in matches:
                        max_str = max(max_str, len(match[1]['name']))
                    for match in matches:
                        header = match[1]['name']
                        header += ' ' * (max_str-len(header))
                        header += ': '
                        self.print_register(match[1], header)
                        print()
                # Add register names to history as a space separated list
                reg_names = [match[1]['name'] for match in matches]
                gdb.add_history(' '.join(reg_names))

    def cmd_load(self, argv, from_tty):
        if len(argv) != 2:
            raise gdb.GdbError("Invalid syntax for subcommand '%s' (expected a string got '%s')." % (argv[0], ' '.join(argv[1:])))
        print("Loading SPR registers database from %s..." % argv[1])
        # Clear our config
        self.regspec_loader = None
        try:
            self.regspec_loader = spr_spec_db.SprSpecDBLoader(argv[1])
        except Exception as e:
            raise gdb.GdbError("Unable to load SPR registers database in '%s': %s." % (argv[1], e))
        print("Loading SPR registers database from %s: done, found %d SPR registers." % (argv[1], len(self.regspec_loader.registers)))

    def cmd_set(self, argv, from_tty):
        if len(argv) < 2:
            raise gdb.GdbError("Invalid syntax, %s command requires a parameter. Try 'help spr'." % argv[0])
        if argv[1] == 'access':
            if len(argv) == 2:
                # Return the current config
                if self.access_mode == 'gdb':
                    print("Currently using GDB register state APIs to access SPRs.")
                elif self.access_mode == 'openocd':
                    print("Currently using OpenOCD's Debug State code injection to access SPRs.")
                else:
                    raise gdb.GdbError("INTERNAL ERROR: unknown access mode %s." % self.access_mode)
                return
            elif len(argv) > 3:
                raise gdb.GdbError("Too many arguments to %s command. Try 'help spr'." % ' '.join(argv[0:1]))
            elif argv[2] in self.supported_access_modes:
                self.access_mode = argv[2]
            else:
                raise gdb.GdbError("Invalid access type '%s'. Try 'help spr'." % argv[2])
            print("Using access mode %s to access SPR registers." % self.access_mode)
        elif argv[1] == 'thread':
            if len(argv) == 2:
                print("Currently accessing SPRs from thread %d." % self.smt_thread)
            elif len(argv) > 3:
                raise gdb.GdbError("Invalid arguments '%s' to %s." % (' '.join(argv[2:]), ' '.join(argv[0:1])))
            else:
                try:
                    th = int(argv[2], 0)
                except:
                    raise gdb.GdbError("Invalid argument '%s' to %s." % (argv[2], ' '.join(argv[0:1])))
                if th >= self.smt_nthreads:
                    raise gdb.GdbError("Thread %d does not exist (max is %d)." % (th, self.smt_nthreads-1))
                self.smt_thread = th
        elif argv[1] == 'debug':
            if len(argv) == 2:
                print("SPR debug mode is currently %s." % ('enabled' if self.debug else 'disabled'))
            elif len(argv) > 3:
                raise gdb.GdbError("Invalid argument '%s' to %s." % (' '.join(argv[2:]), ' '.join(argv[0:1])))
            elif argv[2] == 'on':
                self.debug = True
                print("SPR debug mode is now enabled.")
            elif argv[2] == 'off':
                self.debug = False
                print("SPR debug mode is now disabled.")
            else:
                raise gdb.GdbError("Invalid argument '%s' to %s." % (argv[2], ' '.join(argv[0:1])))
        elif argv[1] == 'quick':
            if len(argv) == 2:
                print("SPR quick mode is currently %s." % ('enabled' if self.quick else 'disabled'))
            elif len(argv) > 3:
                raise gdb.GdbError("Invalid argument '%s' to %s." % (' '.join(argv[2:]), ' '.join(argv[0:1])))
            elif argv[2] == 'on':
                self.quick = True
                print("SPR quick mode is now enabled.")
            elif argv[2] == 'off':
                self.quick = False
                print("SPR quick mode is now disabled.")
            else:
                raise gdb.GdbError("Invalid argument '%s' to %s." % (argv[2], ' '.join(argv[0:1])))
        else:
            raise gdb.GdbError("Unknown %s subcommand %s. Try 'help spr'." % (argv[0], argv[1]))

    def invoke(self, args, from_tty):
        argv = gdb.string_to_argv(args)
        if len(argv) == 0:
            raise gdb.GdbError("The spr command needs arguments, try 'help spr'.")
        elif not argv[0] in self.supported_commands:
            raise gdb.GdbError("Invalid subcommand %s, try 'help spr'." % argv[0])
        elif argv[0] == 'read':
            self.cmd_read(argv, from_tty)
        elif argv[0] == 'write':
            self.cmd_write(argv, from_tty)
        elif argv[0] == 'info':
            self.cmd_info(argv, from_tty)
        elif argv[0] == 'load':
            self.dont_repeat()
            self.cmd_load(argv, from_tty)
        elif argv[0] == 'set':
            self.cmd_set(argv, from_tty)
        else:
            raise gdb.GdbError("INTERNAL ERROR: unhandled command '%s'" % argv[0])

    #########################################################
    # External python APIs. The following functions can be
    # accessed from other python code with:
    # from spr import spr_reg_access
    # spr_reg_access.<api>()
    #########################################################
    def lookup_reg_by_name(self, name):
        """External Python API: use with spr.spr_reg_access object.
        Return the register entry that match <name>. This API assumes only one match is possible.
        """
        if name == None:
            raise gdb.GdbError("lookup_reg_by_name(): Missing name.")
        elif self.regspec_loader == None:
            raise gdb.GdbError("lookup_reg_by_name(): No database loaded, use spr load first.")
        return self.regspec_loader.get_register_by_name(name)

    def read(self, reg):
        """External Python API: use with spr.spr_reg_access object.
        Read an SPR register taking the register as a dictionary as returned by lookup_reg_by_name
        and return the value as a dictionary of fields plus a 'flat' entry containing the whole register value."""
        if reg == None:
            raise gdb.GdbError("read(): Missing register dictionary.")
        # Support passing a string as the register name
        if isinstance(reg, str):
            reg = self.lookup_reg_by_name(reg)
        return self.encode_spr_value(reg, self.read_spr(reg))

    def write(self, reg, value):
        """External Python API: use with spr.spr_reg_access object.
        Write an SPR register taking the register as a dictionary as returned by lookup_reg_by_name
        and a value as a dictionary of fields as returned by encode_spr_value. If a field is not
        specified reset value will be used, if flat is specified it will be assigned first then
        other fields will be used to overwrite flat."""
        if reg == None:
            raise gdb.GdbError("write(): Missing register dictionary.")
        # Support passing a string as the register name
        if isinstance(reg, str):
            reg = self.lookup_reg_by_name(reg)
        if value == None:
            raise gdb.GdbError("write(): Missing value dictionary.")
        # Support passing an integer
        try:
            intv = int(value, 0)
        except:
            intv = self.decode_spr_value(reg, value)
        self.write_spr(reg, intv)

    def encode_spr_value(self, reg, value):
        """External Python API: use with spr.spr_reg_access object.
        Create a dictionary that represent <reg> fields and fill it with <value>.
        Also add an extra entry called 'flat' which contains the whole register value.
        """
        if reg == None:
            raise gdb.GdbError("encode_apb_value(): Missing register dictionary.")
        if 'fields' not in reg:
            raise gdb.GdbError("encode_apb_value(): Missing fields in register dictionary.")
        if (value != None) and not isinstance(value, int):
            raise gdb.GdbError("encode_apb_value(): value when specified must be an integer.")
        regv = {}
        if value != None:
            regv['flat'] = value
        else:
            regv['flat'] = 0
        for field in reg['fields']:
            field_shifted_mask = (1<<(field['bit_hi']-field['bit_lo']+1))-1
            field_shift = field['bit_lo']
            if value != None:
                fieldv = (value >> field_shift) & field_shifted_mask
            elif 'reset_value' in field:
                fieldv = field['reset_value']
                regv['flat'] |= fieldv << field_shift
            else:
                fieldv = 0
            regv[field['name']] = fieldv
        return regv

    def decode_spr_value(self, reg, value = None):
        """External Python API: use with spr.spr_reg_access object.
        Decode a dictionary of fields as returned by encode_spr_value into an integer. If value
        is None then it returns the reset value of the register. If value contains fields that
        are not in the register then they are ignored.
        If value contains 'flat', that word is the base; only register field names also present
        in value replace those bit ranges. With only {'flat': x}, the written value is exactly x.
        Without 'flat', the word is built from 0 using explicit or default field values.
        """
        if reg == None:
            raise gdb.GdbError("decode_spr_value(): Missing register dictionary.")
        if 'fields' not in reg:
            raise gdb.GdbError("decode_spr_value(): Missing fields in register dictionary.")
        use_flat_base = (value != None) and ('flat' in value)
        intv = value['flat'] if use_flat_base else 0
        for field in reg['fields']:
            field_shifted_mask = (1<<(field['bit_hi']-field['bit_lo']+1))-1
            field_shift = field['bit_lo']
            mask = field_shifted_mask << field_shift
            if use_flat_base and field['name'] not in value:
                continue
            if (value != None) and (field['name'] in value):
                fieldv = value[field['name']]
            else:
                fieldv = field['reset_value']
            intv = (intv & ~mask) | ((fieldv & field_shifted_mask) << field_shift)
        return intv

# Instantiate the command
spr_reg_access = spr()

name: Add issue to project
on:
  issues:
    types:
      - opened
jobs:
  track_issue:
    runs-on: ubuntu-latest
    steps:
      - name: Get project data
        env:
          # Need a PAT or GH App to authenticate
          # https://docs.github.com/en/issues/planning-and-tracking-with-projects/automating-your-project/automating-projects-using-actions
          GH_TOKEN: ${{ secrets.YOUR_SECRET }}
          # ex: https://github.com/orgs/rapidsai/projects/41
          # use ORGANIZATION: rapidsai, PROJECT_NUMBER 41
          ORGANIZATION: YOUR_ORG
          PROJECT_NUMBER: YOUR_PROJECT_NUMBER
        run: |
          gh api graphql -f query='
            query($user: String!, $number: Int!) {
              user(login: $user){
                projectV2(number: $number) {
                  id
                }
              }
            }' -f user=$USER -F number=$PROJECT_NUMBER > project_data.json
          echo 'PROJECT_ID='$(jq '.data.user.projectV2.id' project_data.json) >> $GITHUB_ENV

      - name: Add issue to project
        env:
          # Replace with your secret here too
          GITHUB_TOKEN: ${{ secrets.YOUR_SECRET }}
          ISSUE_ID: ${{ github.event.issue.node_id }}
        run: |
          item_id="$( gh api graphql -f query='
            mutation($project:ID!, $issue:ID!) {
              addProjectV2ItemById(input: {projectId: $project, contentId: $issue}) {
                item {
                  id
                }
              }
            }' -f project=$PROJECT_ID -f issue=$ISSUE_ID --jq '.data.addProjectV2ItemById.item.id')"

           echo 'ITEM_ID='$item_id >> $GITHUB_ENV
